/*
  SIGEC-Pro - Sistema Integrado de Gestão
  Ficheiro de Lógica de Aplicação (app.js)
*/

// ==========================================
// 1. ESTADO GLOBAL DA APLICAÇÃO & PERSISTÊNCIA
// ==========================================

const STORAGE_KEYS = {
  CLIENTES: 'sigec_pro_db_clientes_v6',
  CONTACTOS: 'sigec_pro_db_contactos_v6',
  PROJETOS: 'sigec_pro_db_projetos_v6',
  INTERACOES: 'sigec_pro_db_interacoes_v6',
  INTERACOES_PROJETOS: 'sigec_pro_db_interacoes_projetos_v6',
  DELETED_PROJETOS: 'sigec_pro_db_deleted_projetos_v6'
};

let deletedProjectIds = [];

function loadDeletedProjectIds() {
  try {
    let raw = localStorage.getItem(STORAGE_KEYS.DELETED_PROJETOS);
    if (raw === null) raw = localStorage.getItem('centauro_db_deleted_projetos_v6');
    deletedProjectIds = raw ? JSON.parse(raw) : [];
  } catch (e) {
    deletedProjectIds = [];
  }
}

function saveDeletedProjectIds() {
  try {
    localStorage.setItem(STORAGE_KEYS.DELETED_PROJETOS, JSON.stringify(deletedProjectIds));
  } catch (e) {
    console.error('Erro ao guardar lista de projetos eliminados:', e);
  }
}

function addDeletedProjectId(id) {
  if (!id) return;
  if (!deletedProjectIds.includes(id)) {
    deletedProjectIds.push(id);
    saveDeletedProjectIds();
  }
}

function filterDeletedProjects(projectsList) {
  if (!Array.isArray(projectsList)) return [];
  return projectsList.filter(p => p && p.id && !deletedProjectIds.includes(p.id));
}

let db = {
  clientes: [],
  contactos: [],
  projetos: [],
  interacoes: [],
  interacoesProjetos: [],
  usuarios: [],
  userLogs: []
};

let isFormDirty = false;

function markFormDirty() {
  isFormDirty = true;
}

function clearFormDirty() {
  isFormDirty = false;
}

function normalizeText(str) {
  if (str === null || str === undefined) return '';
  return str.toString().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

// Função para Carregar a Base de Dados (Garante persistência de alterações e eliminações permanentes)
function loadDatabase() {
  try {
    loadDeletedProjectIds();

    let rawClientes = localStorage.getItem(STORAGE_KEYS.CLIENTES);
    if (rawClientes === null) rawClientes = localStorage.getItem('centauro_db_clientes_v6');

    let rawContactos = localStorage.getItem(STORAGE_KEYS.CONTACTOS);
    if (rawContactos === null) rawContactos = localStorage.getItem('centauro_db_contactos_v6');

    let rawProjetos = localStorage.getItem(STORAGE_KEYS.PROJETOS);
    if (rawProjetos === null) rawProjetos = localStorage.getItem('centauro_db_projetos_v6');

    let rawInteracoes = localStorage.getItem(STORAGE_KEYS.INTERACOES);
    if (rawInteracoes === null) rawInteracoes = localStorage.getItem('centauro_db_interacoes_v6');

    let rawInteracoesProjetos = localStorage.getItem(STORAGE_KEYS.INTERACOES_PROJETOS);
    if (rawInteracoesProjetos === null) rawInteracoesProjetos = localStorage.getItem('centauro_db_interacoes_projetos_v6');

    let rawUsuarios = localStorage.getItem('sigec_pro_usuarios');
    let rawUserLogs = localStorage.getItem('sigec_pro_user_logs');

    const isFirstTimeRun = (rawClientes === null && rawProjetos === null);

    db.clientes = rawClientes !== null ? JSON.parse(rawClientes) : (typeof INITIAL_EXCEL_DATABASE !== 'undefined' ? [...(INITIAL_EXCEL_DATABASE.clientes || [])] : []);
    db.contactos = rawContactos !== null ? JSON.parse(rawContactos) : (typeof INITIAL_EXCEL_DATABASE !== 'undefined' ? [...(INITIAL_EXCEL_DATABASE.contactos || [])] : []);
    db.projetos = rawProjetos !== null ? filterDeletedProjects(JSON.parse(rawProjetos)) : (typeof INITIAL_EXCEL_DATABASE !== 'undefined' ? filterDeletedProjects([...(INITIAL_EXCEL_DATABASE.projetos || [])]) : []);
    db.interacoes = rawInteracoes !== null ? JSON.parse(rawInteracoes) : [];
    db.interacoesProjetos = rawInteracoesProjetos !== null ? JSON.parse(rawInteracoesProjetos) : [];
    db.usuarios = rawUsuarios !== null ? JSON.parse(rawUsuarios) : [];
    db.userLogs = rawUserLogs !== null ? JSON.parse(rawUserLogs) : [];

    if (typeof ensureUsersInitialized === 'function') ensureUsersInitialized();

    if (isFirstTimeRun && typeof ensureRecoveredProjects === 'function') {
      ensureRecoveredProjects();
    }

    if (typeof purgeGeneratedMockData === 'function') {
      purgeGeneratedMockData();
    }

    saveDatabase();
  } catch (err) {
    console.error('Erro ao carregar base de dados:', err);
    if (typeof INITIAL_EXCEL_DATABASE !== 'undefined') {
      db.clientes = [...(INITIAL_EXCEL_DATABASE.clientes || [])];
      db.contactos = [...(INITIAL_EXCEL_DATABASE.contactos || [])];
      db.projetos = filterDeletedProjects([...(INITIAL_EXCEL_DATABASE.projetos || [])]);
      db.interacoes = [];
      db.interacoesProjetos = [];
      saveDatabase();
    }
  }
}

function ensureRecoveredProjects() {
  const recoveredProjects = [
    {
      "id": "proj-camp-001",
      "clienteId": "cli-imp-086",
      "nome": "Campanha Nacional de Literacia Digital Huawei",
      "tipo": "Ação Comercial",
      "dataInicio": "2026-02-01",
      "dataFim": "2026-06-30",
      "estado": "Adjudicado",
      "viatura": "Huawei SmartBus PT",
      "matricula": "99-HB-22",
      "obs": "Itineração por escolas de Braga, Porto, Gaia, Aveiro, Viseu, Évora, Portimão e Torres Vedras.",
      "createdAt": "2026-07-31T17:00:00.000Z"
    }
  ];

  if (!Array.isArray(deletedProjectIds)) deletedProjectIds = [];
  if (!deletedProjectIds.includes("proj-banc-001")) deletedProjectIds.push("proj-banc-001");
  if (!deletedProjectIds.includes("proj-estrat-2040")) deletedProjectIds.push("proj-estrat-2040");
  deletedProjectIds = deletedProjectIds.filter(id => !["proj-camp-001"].includes(id));
  saveDeletedProjectIds();

  if (!Array.isArray(db.projetos)) db.projetos = [];

  // Purga estrita de qualquer dado fictício/gerado em atualizações anteriores
  purgeGeneratedMockData();

  recoveredProjects.forEach(recProj => {
    const idx = db.projetos.findIndex(p => p.id === recProj.id || (p.nome && p.nome.toLowerCase().includes(recProj.nome.toLowerCase().slice(0, 15))));
    if (idx < 0) {
      db.projetos.push(recProj);
    } else {
      db.projetos[idx] = { ...recProj, ...db.projetos[idx] };
    }
  });
}

function purgeGeneratedMockData() {
  // Função desativada para garantir que nenhum dado de backup importado pelo utilizador seja eliminado ao recarregar a página
}

function loadInitialExcelData() {
  if (typeof INITIAL_EXCEL_DATABASE !== 'undefined') {
    db.clientes = [...(INITIAL_EXCEL_DATABASE.clientes || [])];
    db.contactos = [...(INITIAL_EXCEL_DATABASE.contactos || [])];
    db.projetos = filterDeletedProjects([...(INITIAL_EXCEL_DATABASE.projetos || [])]);
    db.interacoes = [...(INITIAL_EXCEL_DATABASE.interacoes || [])];
    db.interacoesProjetos = [...(INITIAL_EXCEL_DATABASE.interacoesProjetos || [])];
    saveDatabase();
    showToast(`Base de dados importada dos ficheiros Excel: ${db.clientes.length} Clientes e ${db.contactos.length} Contactos!`);
  }
}

function restoreInitialExcelDatabase() {
  const totalCli = (typeof INITIAL_EXCEL_DATABASE !== 'undefined' && INITIAL_EXCEL_DATABASE.clientes) ? INITIAL_EXCEL_DATABASE.clientes.length : 85;
  const totalCon = (typeof INITIAL_EXCEL_DATABASE !== 'undefined' && INITIAL_EXCEL_DATABASE.contactos) ? INITIAL_EXCEL_DATABASE.contactos.length : 192;
  if (confirm(`Tem a certeza que deseja carregar a Base de Dados inicial importada dos ficheiros Excel (${totalCli} Clientes e ${totalCon} Contactos)?`)) {
    loadInitialExcelData();
    renderDatabaseOverview();
    if (db.clientes.length > 0) loadClientIntoForm(db.clientes[0].id);
  }
}

// Helper seguro para guardar chaves no localStorage sem interromper a execução
function safeSetStorage(key, value) {
  try {
    localStorage.setItem(key, value);
    return true;
  } catch (e) {
    console.warn(`Aviso ao guardar ${key} no localStorage:`, e);
    return false;
  }
}

// Função para Guardar a Base de Dados (com gestão tolerante a falhas de quota)
function saveDatabase() {
  let saveSuccess = true;
  try {
    db.projetos = typeof filterDeletedProjects === 'function' ? filterDeletedProjects(db.projetos || []) : (db.projetos || []);

    const s1 = safeSetStorage(STORAGE_KEYS.CLIENTES, JSON.stringify(db.clientes || []));
    const s2 = safeSetStorage(STORAGE_KEYS.CONTACTOS, JSON.stringify(db.contactos || []));

    // Para os projetos, tenta guardar primeiro de forma completa
    let s3 = safeSetStorage(STORAGE_KEYS.PROJETOS, JSON.stringify(db.projetos || []));
    if (!s3) {
      // Se falhar devido ao limite do localStorage (ex: fotos/vídeos grandes),
      // cria uma versão otimizada preservando todos os dados da ficha sem bloquear o sistema
      const lightweightProjects = (db.projetos || []).map(p => {
        if (!p.media || p.media.length === 0) return p;
        return {
          ...p,
          media: p.media.map(m => ({
            id: m.id,
            name: m.name,
            type: m.type,
            mimeType: m.mimeType,
            size: m.size,
            date: m.date
          }))
        };
      });
      s3 = safeSetStorage(STORAGE_KEYS.PROJETOS, JSON.stringify(lightweightProjects));
      if (s3) {
        showToast('Dados guardados! Ficheiros multimédia mantidos em memória.', 'warning');
      }
    }

    const s4 = safeSetStorage(STORAGE_KEYS.INTERACOES, JSON.stringify(db.interacoes || []));
    const s5 = safeSetStorage(STORAGE_KEYS.INTERACOES_PROJETOS, JSON.stringify(db.interacoesProjetos || []));
    safeSetStorage('sigec_pro_usuarios', JSON.stringify(db.usuarios || []));
    safeSetStorage('sigec_pro_user_logs', JSON.stringify(db.userLogs || []));

    if (typeof saveDeletedProjectIds === 'function') saveDeletedProjectIds();

    if (!s1 || !s2 || !s3) {
      saveSuccess = false;
    }
  } catch (err) {
    console.error('Erro ao guardar base de dados local:', err);
    saveSuccess = false;
  }

  // Atualizações visuais da interface executadas com segurança
  try {
    if (typeof renderDatabaseOverview === 'function') renderDatabaseOverview();
    if (typeof updateClientProjectOptions === 'function') updateClientProjectOptions();
    if (typeof renderContactPageMainGrid === 'function') renderContactPageMainGrid();
    if (typeof renderClientPageMainGrid === 'function') renderClientPageMainGrid();
    if (typeof renderProjectPageMainGrid === 'function') renderProjectPageMainGrid();
    if (typeof renderHomeDashboard === 'function') renderHomeDashboard();
  } catch (uiErr) {
    console.error('Erro ao atualizar visualização da interface:', uiErr);
  }

  if (!saveSuccess) {
    showToast('Aviso: Limite de armazenamento local atingido. Exporte um Backup JSON.', 'warning');
  }

  // Sincronização automática em segundo plano com o servidor GitHub (se o Token estiver configurado)
  const ghToken = localStorage.getItem('sigec_pro_gh_token');
  if (ghToken && typeof syncDatabaseToGitHub === 'function') {
    syncDatabaseToGitHub(true);
  }
}

// ==========================================
// 1B. SERVIDOR REMOTO GITHUB (SINCRONIZAÇÃO EM NUVEM - OPÇÃO 2)
// ==========================================

function utf8ToBase64(str) {
  try {
    const bytes = new TextEncoder().encode(str);
    let bin = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
      bin += String.fromCharCode(bytes[i]);
    }
    return window.btoa(bin);
  } catch (e) {
    return window.btoa(unescape(encodeURIComponent(str)));
  }
}

function base64ToUtf8(str) {
  try {
    const bin = window.atob(str);
    const len = bin.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = bin.charCodeAt(i);
    }
    return new TextDecoder().decode(bytes);
  } catch (e) {
    return decodeURIComponent(escape(window.atob(str)));
  }
}

function getGitHubConfig() {
  return {
    owner: localStorage.getItem('sigec_pro_gh_owner') || 'centauropt',
    repo: localStorage.getItem('sigec_pro_gh_repo') || 'SIGEC-Pro',
    path: localStorage.getItem('sigec_pro_gh_path') || 'data/db.json',
    token: localStorage.getItem('sigec_pro_gh_token') || ''
  };
}

function renderGitHubSettingsForm() {
  const cfg = getGitHubConfig();
  const ownerEl = document.getElementById('githubRepoOwner');
  const repoEl = document.getElementById('githubRepoName');
  const pathEl = document.getElementById('githubFilePath');
  const tokenEl = document.getElementById('githubPersonalToken');
  const badge = document.getElementById('githubSyncStatusBadge');

  if (ownerEl) ownerEl.value = cfg.owner;
  if (repoEl) repoEl.value = cfg.repo;
  if (pathEl) pathEl.value = cfg.path;
  if (tokenEl) tokenEl.value = cfg.token;

  if (badge) {
    if (cfg.token) {
      badge.innerHTML = '<i class="fa-solid fa-cloud-check"></i> Servidor Ativo & Ligado';
      badge.style.background = '#dcfce7';
      badge.style.color = '#15803d';
      badge.style.borderColor = '#86efac';
    } else {
      badge.innerHTML = '<i class="fa-solid fa-cloud"></i> Leitura Pública / Sem Token';
      badge.style.background = '#fef9c3';
      badge.style.color = '#a16207';
      badge.style.borderColor = '#fef08a';
    }
  }
}

function handleSaveGitHubSettings(event) {
  if (event && event.preventDefault) event.preventDefault();

  const ownerEl = document.getElementById('githubRepoOwner');
  const repoEl = document.getElementById('githubRepoName');
  const pathEl = document.getElementById('githubFilePath');
  const tokenEl = document.getElementById('githubPersonalToken');

  if (!ownerEl || !repoEl || !pathEl) return;

  const owner = ownerEl.value.trim() || 'centauropt';
  const repo = repoEl.value.trim() || 'SIGEC-Pro';
  const path = pathEl.value.trim() || 'data/db.json';
  const token = tokenEl ? tokenEl.value.trim() : '';

  localStorage.setItem('sigec_pro_gh_owner', owner);
  localStorage.setItem('sigec_pro_gh_repo', repo);
  localStorage.setItem('sigec_pro_gh_path', path);
  localStorage.setItem('sigec_pro_gh_token', token);

  renderGitHubSettingsForm();
  showToast('Definições do servidor GitHub guardadas com sucesso!');
  alert(`✅ Definições do Servidor GitHub Guardadas!\n\nRepositório: ${owner}/${repo}\nFicheiro no Servidor: ${path}\nStatus: ${token ? 'Modo Escrita (Token Configurado)' : 'Modo Leitura'}`);
}

async function syncDatabaseToGitHub(silent = false) {
  const cfg = getGitHubConfig();
  const token = (cfg.token || '').trim();

  if (!token) {
    if (!silent) {
      alert("Aviso: Para sincronizar/enviar dados para o GitHub, insira o seu Token de Acesso Pessoal (PAT) no bloco 'Servidor Remoto GitHub' da página de Configuração.");
    }
    return false;
  }

  const owner = (cfg.owner || 'centauropt').trim();
  const repo = (cfg.repo || 'SIGEC-Pro').trim();
  let path = (cfg.path || 'data/db.json').trim().replace(/^\/+/, '');
  const apiUrl = `https://api.github.com/repos/${owner}/${repo}/contents/${path}`;

  // Formatos de autenticação suportados pelo GitHub API (token ghp_ vs Bearer github_pat_)
  const authHeadersToTry = [
    token.startsWith('github_pat_') ? `Bearer ${token}` : `token ${token}`,
    `token ${token}`,
    `Bearer ${token}`
  ];

  try {
    let existingSha = null;

    // 1. Tenta obter o SHA mais recente com autenticação e fallback sem autenticação
    for (const authHeader of authHeadersToTry) {
      try {
        const getRes = await fetch(apiUrl, {
          method: 'GET',
          headers: {
            'Authorization': authHeader,
            'Accept': 'application/vnd.github.v3+json'
          }
        });
        if (getRes.status === 200) {
          const fileData = await getRes.json();
          if (fileData && fileData.sha) {
            existingSha = fileData.sha;
            break;
          }
        }
      } catch (e) {
        console.warn('Tentativa GET com auth falhou:', e);
      }
    }

    // Fallback público (caso o repositório seja público)
    if (!existingSha) {
      try {
        const publicRes = await fetch(apiUrl, {
          method: 'GET',
          headers: {
            'Accept': 'application/vnd.github.v3+json'
          }
        });
        if (publicRes.status === 200) {
          const fileData = await publicRes.json();
          if (fileData && fileData.sha) existingSha = fileData.sha;
        }
      } catch (e) {
        console.warn('Tentativa GET pública falhou:', e);
      }
    }

    const dbString = JSON.stringify(db, null, 2);
    const contentBase64 = utf8ToBase64(dbString);

    const sendPutWithHeader = async (shaVal, authHdr) => {
      const payload = {
        message: `Atualização automática de dados SIGEC-Pro - ${new Date().toISOString()}`,
        content: contentBase64
      };
      if (shaVal) payload.sha = shaVal;

      return await fetch(apiUrl, {
        method: 'PUT',
        headers: {
          'Authorization': authHdr,
          'Content-Type': 'application/json',
          'Accept': 'application/vnd.github.v3+json'
        },
        body: JSON.stringify(payload)
      });
    };

    let primaryAuthHeader = authHeadersToTry[0];
    let putRes = await sendPutWithHeader(existingSha, primaryAuthHeader);

    // Se falhar com 409 (SHA mismatch), 422 ou 401, extrai o SHA retornado pela mensagem do GitHub e faz a re-tentativa imediata
    if (!putRes.ok) {
      let errBodyText = "";
      try {
        const errJson = await putRes.clone().json();
        errBodyText = errJson.message || JSON.stringify(errJson);
      } catch (e) {
        errBodyText = await putRes.clone().text().catch(() => "");
      }

      const match = errBodyText.match(/does not match ([a-f0-9]{40})/i);
      if (match && match[1]) {
        const targetSha = match[1];
        putRes = await sendPutWithHeader(targetSha, primaryAuthHeader);
      }

      if (!putRes.ok && (putRes.status === 409 || putRes.status === 422 || putRes.status === 401)) {
        for (const altAuth of authHeadersToTry) {
          const freshRes = await fetch(apiUrl, {
            method: 'GET',
            headers: { 'Authorization': altAuth, 'Accept': 'application/vnd.github.v3+json' }
          }).catch(() => null);

          let freshSha = existingSha;
          if (freshRes && freshRes.status === 200) {
            const freshData = await freshRes.json();
            if (freshData && freshData.sha) freshSha = freshData.sha;
          }

          putRes = await sendPutWithHeader(freshSha, altAuth);
          if (putRes.ok) break;

          if (!putRes.ok) {
            const altErrText = await putRes.clone().text().catch(() => "");
            const altMatch = altErrText.match(/does not match ([a-f0-9]{40})/i);
            if (altMatch && altMatch[1]) {
              putRes = await sendPutWithHeader(altMatch[1], altAuth);
              if (putRes.ok) break;
            }
          }
        }
      }
    }

    if (putRes.status === 200 || putRes.status === 201) {
      localStorage.setItem('sigec_pro_last_gh_sync', new Date().toISOString());
      if (typeof logUserActivity === 'function') {
        logUserActivity('Servidor GitHub', `Dados sincronizados com sucesso no servidor GitHub (${owner}/${repo}).`);
      }
      if (!silent) {
        showToast('Dados sincronizados com o servidor GitHub!');
        alert(`✅ Sincronização Concluída com Sucesso!\n\nTodos os dados do programa foram registados e salvaguardados no servidor GitHub (${owner}/${repo}).`);
      }
      return true;
    } else {
      const errData = await putRes.json().catch(() => ({ message: 'Erro desconhecido' }));
      console.error('Erro ao enviar dados para GitHub:', putRes.status, errData);
      
      if (!silent) {
        if (putRes.status === 404) {
          alert(`Erro de Ligação (404 Not Found):\n\nO GitHub não encontrou o repositório "${owner}/${repo}". Verifique o utilizador e repositório.`);
        } else if (putRes.status === 401) {
          alert(`Erro de Autenticação (401 Unauthorized):\n\nO Token introduzido é inválido ou expirou. Verifique o Token no bloco 'Servidor Remoto GitHub'.`);
        } else {
          alert(`Erro na Sincronização com o Servidor GitHub (${putRes.status}):\n\n${errData.message || 'Falha ao autenticar ou gravar no repositório.'}`);
        }
      }
      return false;
    }
  } catch (err) {
    console.error('Falha de ligação ao servidor GitHub:', err);
    if (!silent) {
      alert(`Falha de Ligação:\nNão foi possível contactar o servidor GitHub: ${err.message}`);
    }
    return false;
  }
}

async function loadDatabaseFromGitHub(silent = false) {
  const cfg = getGitHubConfig();
  const token = (cfg.token || '').trim();
  const authHeader = token ? (token.startsWith('github_pat_') ? `Bearer ${token}` : `token ${token}`) : null;

  try {
    const apiUrl = `https://api.github.com/repos/${cfg.owner}/${cfg.repo}/contents/${cfg.path}`;
    const headers = { 'Accept': 'application/vnd.github.v3.raw' };
    if (authHeader) headers['Authorization'] = authHeader;

    const res = await fetch(apiUrl, { method: 'GET', headers: headers, cache: 'no-store' });

    if (!res.ok) {
      if (!silent) alert(`Não foi possível encontrar o ficheiro de dados no servidor GitHub (${apiUrl}).`);
      return false;
    }

    const remoteDb = await res.json();
    if (!remoteDb || typeof remoteDb !== 'object') return false;

    if (Array.isArray(remoteDb.clientes)) {
      remoteDb.clientes.forEach(incCli => {
        const idx = db.clientes.findIndex(c => c.id === incCli.id);
        if (idx >= 0) {
          db.clientes[idx] = { ...incCli, ...db.clientes[idx] };
        } else {
          db.clientes.push(incCli);
        }
      });
    }

    if (Array.isArray(remoteDb.contactos)) {
      remoteDb.contactos.forEach(incCon => {
        const idx = db.contactos.findIndex(c => c.id === incCon.id);
        if (idx >= 0) {
          db.contactos[idx] = { ...incCon, ...db.contactos[idx] };
        } else {
          db.contactos.push(incCon);
        }
      });
    }

    if (Array.isArray(remoteDb.projetos)) {
      remoteDb.projetos.forEach(incProj => {
        const idx = db.projetos.findIndex(p => p.id === incProj.id);
        if (idx >= 0) {
          db.projetos[idx] = { ...incProj, ...db.projetos[idx] };
        } else {
          db.projetos.push(incProj);
        }
      });
    }

    if (Array.isArray(remoteDb.usuarios)) {
      remoteDb.usuarios.forEach(incUser => {
        const idx = db.usuarios.findIndex(u => u.id === incUser.id);
        if (idx >= 0) {
          db.usuarios[idx] = { ...incUser, ...db.usuarios[idx] };
        } else {
          db.usuarios.push(incUser);
        }
      });
    }

    saveDatabase();

    if (!silent) {
      showToast('Dados do servidor GitHub carregados com sucesso!');
      alert(`✅ Dados do Servidor Carregados!\n\nA base de dados do programa foi sincronizada a partir do servidor GitHub com sucesso.`);
    }
    return true;
  } catch (err) {
    console.error('Erro ao carregar dados do GitHub:', err);
    if (!silent) alert(`Erro ao carregar dados do servidor GitHub: ${err.message}`);
    return false;
  }
}

async function handleFullServerSync(silent = false) {
  const ghToken = localStorage.getItem('sigec_pro_gh_token');
  if (!ghToken) {
    if (!silent) {
      alert("Aviso: Para sincronizar os dados com o servidor GitHub, insira o seu Token de Acesso Pessoal (PAT) no campo abaixo e clique em 'Guardar Definições do Servidor'.");
    }
    return false;
  }

  saveDatabase();

  if (!silent) showToast('A sincronizar com o servidor GitHub...', 'info');

  const uploadSuccess = await syncDatabaseToGitHub(silent);

  saveDatabase();
  renderDatabaseOverview();

  return uploadSuccess;
}

// Gerador de UUIDs simples
function generateId(prefix = 'id') {
  return `${prefix}-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
}

// ==========================================
// 2. INICIALIZAÇÃO DA INTERFACE & NAVEGAÇÃO
// ==========================================

document.addEventListener('DOMContentLoaded', () => {
  loadDatabase();
  initFormListeners();
  renderDatabaseOverview();
  renderClientPageMainGrid();
  renderProjectPageMainGrid();
  renderContactPageMainGrid();
  renderHomeDashboard();

  // Escutar alterações nos campos para controlo de confirmação de edições
  document.addEventListener('input', (e) => {
    if (['INPUT', 'TEXTAREA', 'SELECT'].includes(e.target.tagName)) {
      if (!e.target.id.includes('SearchQuery') && e.target.id !== 'searchCategory') {
        markFormDirty();
      }
    }
  });

  document.addEventListener('change', (e) => {
    if (['INPUT', 'TEXTAREA', 'SELECT'].includes(e.target.tagName)) {
      if (!e.target.id.includes('SearchQuery') && e.target.id !== 'searchCategory') {
        markFormDirty();
      }
    }
  });

  window.addEventListener('beforeunload', (e) => {
    if (isFormDirty) {
      e.preventDefault();
      e.returnValue = 'Existem alterações não guardadas.';
    }
  });

  resetClientForm(true);
  switchTab('tab-home');
});

function switchTab(tabId) {
  if (isFormDirty) {
    if (!confirm('Existem alterações não guardadas no formulário. Deseja sair sem guardar?')) {
      return;
    }
    clearFormDirty();
  }

  // Fechar qualquer modal de ficha que esteja aberto ao mudar de página
  document.getElementById('clientModal')?.classList.remove('active');
  document.getElementById('projectModal')?.classList.remove('active');
  document.getElementById('contactModal')?.classList.remove('active');

  document.querySelectorAll('.tab-content').forEach(tab => tab.classList.remove('active'));
  document.querySelectorAll('.nav-btn').forEach(btn => btn.classList.remove('active'));

  const targetTab = document.getElementById(tabId);
  const targetBtn = document.querySelector(`.nav-btn[data-tab="${tabId}"]`);

  if (targetTab) targetTab.classList.add('active');
  if (targetBtn) targetBtn.classList.add('active');

  if (tabId === 'tab-database') {
    renderDatabaseOverview();
  } else if (tabId === 'tab-contactos') {
    renderContactPageMainGrid();
  } else if (tabId === 'tab-clientes') {
    renderClientPageMainGrid();
  } else if (tabId === 'tab-projetos') {
    updateClientProjectOptions();
    renderProjectPageMainGrid();
  } else if (tabId === 'tab-home') {
    renderHomeDashboard();
  }
}

function switchDbSubTab(subTabName) {
  document.querySelectorAll('.db-subtab-btn').forEach(btn => btn.classList.remove('active'));
  document.querySelectorAll('.db-subtab-content').forEach(content => content.classList.remove('active'));

  const btn = document.getElementById(`dbSubtabBtn-${subTabName}`);
  const content = document.getElementById(`dbSubtabContent-${subTabName}`);

  if (btn) btn.classList.add('active');
  if (content) content.classList.add('active');
}

function renderContactPageMainGrid() {
  const container = document.getElementById('contactPageMainGrid');
  if (!container) return;
  container.innerHTML = '';

  const query = document.getElementById('contactPageSearchQuery')?.value.trim() || '';
  let contactsList = [...(db.contactos || [])];

  if (query) {
    const qNorm = normalizeText(query);
    contactsList = contactsList.filter(con => {
      const client = db.clientes.find(c => c.id === con.clienteId);
      const clientName = client ? normalizeText(client.nome) : '';
      return (
        normalizeText(con.nome).includes(qNorm) ||
        normalizeText(con.apelido).includes(qNorm) ||
        normalizeText(con.cargo).includes(qNorm) ||
        normalizeText(con.email).includes(qNorm) ||
        normalizeText(con.telefone).includes(qNorm) ||
        normalizeText(con.telemovel).includes(qNorm) ||
        normalizeText(con.notas).includes(qNorm) ||
        clientName.includes(qNorm)
      );
    });
  }

  // Ordenação Alfabética Obrigatória A-Z
  contactsList.sort((a, b) => {
    const nameA = `${a.nome || ''} ${a.apelido || ''}`.trim();
    const nameB = `${b.nome || ''} ${b.apelido || ''}`.trim();
    return nameA.localeCompare(nameB, 'pt', { sensitivity: 'base' });
  });

  if (contactsList.length === 0) {
    container.innerHTML = '<span class="empty-state">Nenhum contacto encontrado para os critérios de pesquisa.</span>';
    return;
  }

  if (typeof contactViewMode !== 'undefined' && contactViewMode === 'list') {
    let html = `
      <table class="db-table" style="width:100%; border-collapse:collapse; font-size:0.88rem;">
        <thead>
          <tr style="background-color:#e0f2fe; color:#1e3a8a;">
            <th style="padding:0.75rem 1rem; text-align:left;">Nome do Contacto</th>
            <th style="padding:0.75rem 1rem; text-align:left;">Cliente Associado</th>
            <th style="padding:0.75rem 1rem; text-align:left;">Cargo</th>
            <th style="padding:0.75rem 1rem; text-align:left;">Telemóvel / Telefone</th>
            <th style="padding:0.75rem 1rem; text-align:left;">Email</th>
            <th style="padding:0.75rem 1rem; text-align:center;">Ações</th>
          </tr>
        </thead>
        <tbody>
    `;

    contactsList.forEach(con => {
      const client = db.clientes.find(c => c.id === con.clienteId);
      html += `
        <tr style="border-bottom:1px solid #e2e8f0;">
          <td style="padding:0.75rem 1rem; font-weight:700; color:#1e293b;">${escapeHtml(con.nome)} ${escapeHtml(con.apelido || '')}</td>
          <td style="padding:0.75rem 1rem; color:#334155;">${escapeHtml(client ? client.nome : '-')}</td>
          <td style="padding:0.75rem 1rem; color:#475569;">${escapeHtml(con.cargo || '-')}</td>
          <td style="padding:0.75rem 1rem; color:#475569;">${escapeHtml(con.telemovel || con.telefone || '-')}</td>
          <td style="padding:0.75rem 1rem; color:#475569;">${escapeHtml(con.email || '-')}</td>
          <td style="padding:0.75rem 1rem; text-align:center; white-space:nowrap;">
            <button type="button" class="action-icon-btn" onclick="openTransferContactModal('${con.id}')" title="Mudar de Cliente">
              <i class="fa-solid fa-arrow-right-arrow-left"></i>
            </button>
            <button type="button" class="action-icon-btn" onclick="openContactModalForEdit('${con.id}')" title="Editar Ficha de Contacto">
              <i class="fa-solid fa-pen-to-square"></i>
            </button>
            <button type="button" class="action-icon-btn danger" onclick="deleteContactInline('${con.id}')" title="Apagar Contacto">
              <i class="fa-solid fa-trash"></i>
            </button>
          </td>
        </tr>
      `;
    });

    html += '</tbody></table>';
    container.innerHTML = html;
  } else {
    container.className = 'contacts-grid';
    contactsList.forEach(con => {
      const client = db.clientes.find(c => c.id === con.clienteId);
      const clientName = client ? client.nome : 'N/D';

      const card = document.createElement('div');
      card.className = 'contact-card';
      card.innerHTML = `
        <div class="contact-card-actions">
          <button type="button" class="action-icon-btn" onclick="openTransferContactModal('${con.id}')" title="Mudar de Cliente">
            <i class="fa-solid fa-arrow-right-arrow-left"></i>
          </button>
          <button type="button" class="action-icon-btn" onclick="openContactModalForEdit('${con.id}')" title="Editar Ficha de Contacto">
            <i class="fa-solid fa-pen-to-square"></i>
          </button>
          <button type="button" class="action-icon-btn danger" onclick="deleteContactInline('${con.id}')" title="Apagar Contacto">
            <i class="fa-solid fa-trash"></i>
          </button>
        </div>
        <div class="contact-name">${escapeHtml(con.nome)} ${escapeHtml(con.apelido || '')}</div>
        <div class="contact-role"><i class="fa-solid fa-briefcase"></i> ${escapeHtml(con.cargo || 'Contacto')}</div>
        <div class="contact-detail" style="font-weight: 500; color: var(--primary-blue);"><i class="fa-solid fa-building"></i> ${escapeHtml(clientName)}</div>
        ${con.telefone ? `<div class="contact-detail"><i class="fa-solid fa-phone"></i> ${escapeHtml(con.telefone)}</div>` : ''}
        ${con.telemovel ? `<div class="contact-detail"><i class="fa-solid fa-mobile-screen"></i> ${escapeHtml(con.telemovel)}</div>` : ''}
        ${con.email ? `<div class="contact-detail"><i class="fa-solid fa-envelope"></i> ${escapeHtml(con.email)}</div>` : ''}
        ${con.notas ? `<div class="contact-notes-preview" title="${escapeHtmlAttr(con.notas)}"><strong>Notas:</strong> ${escapeHtml(con.notas)}</div>` : ''}
      `;
      container.appendChild(card);
    });
  }
}

