// ==========================================
// 17. DUPLICAÇÃO DE PROJETOS
// ==========================================

function duplicateCurrentProject() {
  if (!currentProjectId) {
    showToast('Selecione ou guarde um projeto primeiro!', 'danger');
    return;
  }
  duplicateProjectById(currentProjectId);
}

function duplicateProjectInline(projectId, event) {
  if (event) event.stopPropagation();
  duplicateProjectById(projectId);
}

function duplicateProjectById(projectId) {
  const project = db.projetos.find(p => p.id === projectId);
  if (!project) return;

  const clone = JSON.parse(JSON.stringify(project));
  clone.id = generateId('proj');
  clone.nome = `${project.nome || 'Projeto'} (Cópia)`;
  clone.createdAt = new Date().toISOString();
  if (!clone.media) clone.media = [];
  if (!clone.documents) clone.documents = [];

  // Duplicar também os registos e notas de contactos/interações do projeto
  const projectInteractions = (db.interacoesProjetos || []).filter(i => i.projectId === projectId);
  projectInteractions.forEach(inter => {
    const interClone = JSON.parse(JSON.stringify(inter));
    interClone.id = 'proji-' + Date.now() + '-' + Math.random().toString(36).substr(2, 5);
    interClone.projectId = clone.id;
    interClone.createdAt = new Date().toISOString();
    if (!db.interacoesProjetos) db.interacoesProjetos = [];
    db.interacoesProjetos.push(interClone);
  });

  db.projetos.push(clone);
  saveDatabase();
  renderProjectPageMainGrid();
  loadProjectIntoForm(clone.id, true, true);

  setTimeout(() => {
    const nameInput = document.getElementById('projectNome');
    if (nameInput) {
      nameInput.focus();
      nameInput.select();
    }
  }, 150);

  showToast(`Projeto duplicado com sucesso como "${clone.nome}"! Pode renomear o projeto agora.`);
}

// ==========================================
// 18. MOVER CONTACTO ENTRE SEPARADORES ESTATICA
// ==========================================

let currentMoveSubTabContactId = null;

function openMoveSubTabContactModal(contactId) {
  const contact = db.contactos.find(c => c.id === contactId);
  if (!contact) return;

  currentMoveSubTabContactId = contact.id;
  document.getElementById('moveSubTabContactId').value = contact.id;
  document.getElementById('moveSubTabContactInfo').innerHTML = `Contacto: <strong>${escapeHtml(contact.nome)} ${escapeHtml(contact.apelido || '')}</strong>`;

  const select = document.getElementById('targetSubTabIndex');
  select.innerHTML = '';

  currentEstatalSeparadores.forEach((sep, idx) => {
    const opt = document.createElement('option');
    opt.value = idx;
    opt.textContent = `${idx + 1}. ${sep.tipoSeparador || 'Separador'}`;
    if (contact.subTabIndex === idx) {
      opt.textContent += ' (Atual)';
      opt.disabled = true;
    }
    select.appendChild(opt);
  });

  document.getElementById('moveSubTabContactModal').classList.add('active');
}

function closeMoveSubTabContactModal() {
  const modal = document.getElementById('moveSubTabContactModal');
  if (modal) modal.classList.remove('active');
  currentMoveSubTabContactId = null;
}

function saveMoveSubTabContact(e) {
  e.preventDefault();
  if (!currentMoveSubTabContactId) return;

  const contact = db.contactos.find(c => c.id === currentMoveSubTabContactId);
  if (!contact) return;

  const targetIdx = parseInt(document.getElementById('targetSubTabIndex').value, 10);
  contact.subTabIndex = targetIdx;
  saveDatabase();
  closeMoveSubTabContactModal();
  renderEstatalSeparadores();
  if (currentClientId) {
    refreshClientSubLists(currentClientId);
  }
  const targetSep = currentEstatalSeparadores[targetIdx];
  const targetName = targetSep ? getSeparadorTitle(targetSep) : 'novo separador';
  showToast(`Contacto movido com sucesso para o separador "${targetName}"!`);
}

function openContactModalForSubTab(subTabIndex) {
  if (!currentClientId) {
    showToast('Guarde ou selecione um Cliente primeiro!', 'danger');
    return;
  }
  openContactModalForNew();
}

// ==========================================
// 19. PREVENÇÃO & CAIXA DE DIÁLOGO DE DUPLICADOS
// ==========================================

let pendingDuplicateData = null;

function checkForDuplicateClient(clientObj, existingId = null) {
  if (!db || !db.clientes) return null;
  const nameNorm = normalizeText(clientObj.nome);
  const nifNorm = (clientObj.contribuinte || '').trim();
  const emailNorm = (clientObj.email || '').trim().toLowerCase();
  const phoneNorm = (clientObj.telemovel || clientObj.telefone || '').replace(/\D/g, '');

  return db.clientes.find(c => {
    if (existingId && c.id === existingId) return false;
    const cNameNorm = normalizeText(c.nome);
    const cNifNorm = (c.contribuinte || '').trim();
    const cEmailNorm = (c.email || '').trim().toLowerCase();
    const cPhoneNorm = (c.telemovel || c.telefone || '').replace(/\D/g, '');

    if (nifNorm && cNifNorm && nifNorm.length >= 7 && nifNorm === cNifNorm) return true;
    if (nameNorm && cNameNorm && nameNorm === cNameNorm) return true;
    if (emailNorm && cEmailNorm && emailNorm.length > 3 && emailNorm === cEmailNorm) return true;
    if (phoneNorm && cPhoneNorm && phoneNorm.length >= 9 && phoneNorm === cPhoneNorm) return true;

    return false;
  });
}

function checkForDuplicateContact(contactObj, existingId = null) {
  if (!db || !db.contactos) return null;
  const nameNorm = normalizeText(`${contactObj.nome || ''} ${contactObj.apelido || ''}`);
  const emailNorm = (contactObj.email || '').trim().toLowerCase();
  const phoneNorm = (contactObj.telemovel || contactObj.telefone || '').replace(/\D/g, '');

  return db.contactos.find(c => {
    if (existingId && c.id === existingId) return false;
    const cNameNorm = normalizeText(`${c.nome || ''} ${c.apelido || ''}`);
    const cEmailNorm = (c.email || '').trim().toLowerCase();
    const cPhoneNorm = (c.telemovel || c.telefone || '').replace(/\D/g, '');

    if (emailNorm && cEmailNorm && emailNorm.length > 3 && emailNorm === cEmailNorm) return true;
    if (phoneNorm && cPhoneNorm && phoneNorm.length >= 9 && phoneNorm === cPhoneNorm) return true;
    if (nameNorm && cNameNorm && nameNorm.length > 2 && nameNorm === cNameNorm) return true;

    return false;
  });
}

function checkForDuplicateProject(projectObj, existingId = null) {
  if (!db || !db.projetos) return null;
  const nameNorm = normalizeText(projectObj.nome);
  const matNorm = (projectObj.matricula || '').replace(/[^A-Za-z0-9]/g, '').toUpperCase();

  return db.projetos.find(p => {
    if (existingId && p.id === existingId) return false;
    const pNameNorm = normalizeText(p.nome);
    const pMatNorm = (p.matricula || '').replace(/[^A-Za-z0-9]/g, '').toUpperCase();

    if (nameNorm && pNameNorm && nameNorm === pNameNorm) return true;
    if (matNorm && pMatNorm && matNorm.length >= 6 && matNorm === pMatNorm) return true;

    return false;
  });
}

function checkAndHandleDuplicates(type, newObj, existingId, onProceed) {
  let existingMatch = null;
  if (type === 'cliente') {
    existingMatch = checkForDuplicateClient(newObj, existingId);
  } else if (type === 'contacto') {
    existingMatch = checkForDuplicateContact(newObj, existingId);
  } else if (type === 'projeto') {
    existingMatch = checkForDuplicateProject(newObj, existingId);
  }

  if (existingMatch) {
    pendingDuplicateData = {
      type,
      newObj,
      existingMatch,
      onProceed
    };

    const typeLabel = type === 'cliente' ? 'Cliente' : (type === 'contacto' ? 'Contacto' : 'Projeto');
    let existingName = existingMatch.nome || 'Registo';
    if (type === 'contacto') {
      existingName = `${existingMatch.nome || ''} ${existingMatch.apelido || ''}`.trim();
    }
    const detail = existingMatch.contribuinte ? `(NIF: ${existingMatch.contribuinte})` : (existingMatch.email ? `(Email: ${existingMatch.email})` : '');

    const textEl = document.getElementById('duplicateModalText');
    if (textEl) {
      textEl.innerHTML = `Foi detetado que já existe um <strong>${typeLabel}</strong> na base de dados idêntico ao que está a introduzir:<br><strong style="font-size:1rem; color:#1e3a8a;">"${escapeHtml(existingName)}"</strong> ${escapeHtml(detail)}.`;
    }
    const modal = document.getElementById('duplicateResolutionModal');
    if (modal) modal.classList.add('active');
    return true;
  }
  return false;
}

function closeDuplicateResolutionModal() {
  const modal = document.getElementById('duplicateResolutionModal');
  if (modal) modal.classList.remove('active');
  pendingDuplicateData = null;
}

function resolveDuplicateAction(action) {
  if (!pendingDuplicateData) {
    closeDuplicateResolutionModal();
    return;
  }

  const { type, newObj, existingMatch, onProceed } = pendingDuplicateData;

  if (action === 'keep_existing') {
    showToast('Registo novo descartado. Mantida a ficha anterior intacta.', 'warning');
    closeDuplicateResolutionModal();
  } else if (action === 'replace_existing') {
    newObj.id = existingMatch.id;
    if (type === 'cliente') {
      const idx = db.clientes.findIndex(c => c.id === existingMatch.id);
      if (idx >= 0) db.clientes[idx] = newObj;
      if (typeof closeClientModal === 'function') closeClientModal();
      renderClientPageMainGrid();
    } else if (type === 'contacto') {
      const idx = db.contactos.findIndex(c => c.id === existingMatch.id);
      if (idx >= 0) db.contactos[idx] = newObj;
      if (typeof closeContactModal === 'function') closeContactModal();
      renderContactPageMainGrid();
    } else if (type === 'projeto') {
      const idx = db.projetos.findIndex(p => p.id === existingMatch.id);
      if (idx >= 0) db.projetos[idx] = newObj;
      if (typeof closeProjectModal === 'function') closeProjectModal();
      renderProjectPageMainGrid();
    }
    saveDatabase();
    renderHomeDashboard();
    renderDatabaseOverview();
    closeDuplicateResolutionModal();
    if (onProceed) onProceed(existingMatch.id);
    showToast('Registo anterior substituído e atualizado com os novos dados!');
  } else if (action === 'merge') {
    // Combinar informações: preencher campos em falta na ficha existente com os novos dados
    Object.keys(newObj).forEach(key => {
      if (key === 'id') return;
      if (Array.isArray(newObj[key])) {
        if (!existingMatch[key]) existingMatch[key] = [];
        newObj[key].forEach(item => {
          if (item && item.id && !existingMatch[key].some(e => e.id === item.id)) {
            existingMatch[key].push(item);
          }
        });
      } else if (newObj[key] !== null && newObj[key] !== undefined && newObj[key] !== '') {
        if (!existingMatch[key]) {
          existingMatch[key] = newObj[key];
        }
      }
    });

    if (type === 'cliente') {
      if (typeof closeClientModal === 'function') closeClientModal();
      renderClientPageMainGrid();
    } else if (type === 'contacto') {
      if (typeof closeContactModal === 'function') closeContactModal();
      renderContactPageMainGrid();
    } else if (type === 'projeto') {
      if (typeof closeProjectModal === 'function') closeProjectModal();
      renderProjectPageMainGrid();
    }

    saveDatabase();
    renderHomeDashboard();
    renderDatabaseOverview();
    closeDuplicateResolutionModal();
    if (onProceed) onProceed(existingMatch.id);
    showToast('Informações dos dois registos combinadas com sucesso!');
  }
}

// ==========================================
// 20. TRANSFERÊNCIA DE CONTACTO ENTRE CLIENTES E SEPARADORES ESTATICA
// ==========================================

function openTransferContactModal(contactId) {
  const contact = db.contactos.find(c => c.id === contactId);
  if (!contact) return;

  window.currentTransferContactId = contact.id;
  document.getElementById('transferContactId').value = contact.id;

  const currentClient = db.clientes.find(c => c.id === contact.clienteId);
  const currentClientName = currentClient ? currentClient.nome : 'Sem cliente';

  document.getElementById('transferContactName').textContent = `${contact.nome} ${contact.apelido || ''}`.trim();
  document.getElementById('transferCurrentClientName').textContent = currentClientName;

  const clientSelect = document.getElementById('transferTargetClientId');
  clientSelect.innerHTML = '<option value="">-- Selecione o Novo Cliente --</option>';

  const sortedClients = [...(db.clientes || [])].sort((a, b) => (a.nome || '').localeCompare(b.nome || '', 'pt', { sensitivity: 'base' }));

  sortedClients.forEach(cli => {
    const opt = document.createElement('option');
    opt.value = cli.id;
    let label = `${cli.nome} (${cli.tipoCliente})`;
    if (cli.id === contact.clienteId) {
      label += ' (Atual)';
    }
    opt.textContent = label;
    clientSelect.appendChild(opt);
  });

  const subTabGroup = document.getElementById('transferSubTabGroup');
  if (subTabGroup) subTabGroup.style.display = 'none';
  const subTabSelect = document.getElementById('transferTargetSubTabIndex');
  if (subTabSelect) {
    subTabSelect.innerHTML = '';
    subTabSelect.removeAttribute('required');
  }

  document.getElementById('transferContactModal').classList.add('active');
}

function handleTransferTargetClientChange() {
  const select = document.getElementById('transferTargetClientId');
  const targetId = select ? select.value : '';
  const subTabGroup = document.getElementById('transferSubTabGroup');
  const subTabSelect = document.getElementById('transferTargetSubTabIndex');
  if (!subTabGroup || !subTabSelect) return;

  if (!targetId) {
    subTabGroup.style.display = 'none';
    subTabSelect.removeAttribute('required');
    subTabSelect.innerHTML = '';
    return;
  }

  const targetClient = db.clientes.find(c => c.id === targetId);
  if (targetClient && targetClient.tipoCliente === 'Estatal') {
    subTabGroup.style.display = 'block';
    subTabSelect.setAttribute('required', 'true');
    subTabSelect.innerHTML = '';

    const separadores = targetClient.separadores && Array.isArray(targetClient.separadores) && targetClient.separadores.length > 0
      ? targetClient.separadores
      : [{ tipoSeparador: 'Gabinete Principal' }];

    separadores.forEach((sep, idx) => {
      const opt = document.createElement('option');
      opt.value = idx;
      const title = getSeparadorTitle(sep);
      const sepNome = sep.nome ? ` - ${sep.nome}` : '';
      opt.textContent = `${idx + 1}. ${title}${sepNome}`;
      subTabSelect.appendChild(opt);
    });
  } else {
    subTabGroup.style.display = 'none';
    subTabSelect.removeAttribute('required');
    subTabSelect.innerHTML = '';
  }
}

function closeTransferContactModal() {
  const modal = document.getElementById('transferContactModal');
  if (modal) modal.classList.remove('active');
  window.currentTransferContactId = null;
}

function saveTransferContact(e) {
  e.preventDefault();
  const contactId = window.currentTransferContactId || document.getElementById('transferContactId')?.value;
  if (!contactId) return;

  const contact = db.contactos.find(c => c.id === contactId);
  if (!contact) return;

  const targetClientId = document.getElementById('transferTargetClientId').value;
  if (!targetClientId) {
    showToast('Por favor, selecione um cliente de destino.', 'danger');
    return;
  }

  const targetClient = db.clientes.find(c => c.id === targetClientId);
  if (!targetClient) return;

  let targetSubTabTitle = '';
  if (targetClient.tipoCliente === 'Estatal') {
    const subTabSelect = document.getElementById('transferTargetSubTabIndex');
    const subIdx = parseInt(subTabSelect ? subTabSelect.value : '0', 10) || 0;
    contact.subTabIndex = subIdx;

    const seps = targetClient.separadores || [];
    if (seps[subIdx]) {
      targetSubTabTitle = getSeparadorTitle(seps[subIdx]);
    } else {
      targetSubTabTitle = `Separador ${subIdx + 1}`;
    }
  } else {
    contact.subTabIndex = 0;
  }

  contact.clienteId = targetClientId;
  saveDatabase();
  closeTransferContactModal();

  if (currentClientId) {
    refreshClientSubLists(currentClientId);
  }
  renderDatabaseOverview();
  renderContactPageMainGrid();

  if (targetSubTabTitle) {
    showToast(`Contacto transferido com sucesso para "${targetClient.nome}" (Separador: ${targetSubTabTitle})!`);
  } else {
    showToast(`Contacto transferido com sucesso para "${targetClient.nome}"!`);
  }
}

// ==========================================
// 19. REDIMENSIONAMENTO DE JANELAS POP-UP COM O RATO
// ==========================================

function initModalResizing() {
  const modalWindows = document.querySelectorAll('.modal-window');
  
  modalWindows.forEach(win => {
    if (win.querySelector('.modal-resize-handle')) return;

    const handles = ['t', 'r', 'b', 'l', 'tl', 'tr', 'bl', 'br'];
    handles.forEach(h => {
      const handleDiv = document.createElement('div');
      handleDiv.className = `modal-resize-handle handle-${h}`;
      handleDiv.dataset.handle = h;
      win.appendChild(handleDiv);

      handleDiv.addEventListener('mousedown', (e) => startResizingModal(e, win, h));
    });
  });
}

function startResizingModal(e, win, handle) {
  e.preventDefault();
  e.stopPropagation();

  const startX = e.clientX;
  const startY = e.clientY;
  const rect = win.getBoundingClientRect();
  const startWidth = rect.width;
  const startHeight = rect.height;

  const origTransition = win.style.transition;
  win.style.transition = 'none';

  function onMouseMove(moveEvt) {
    moveEvt.preventDefault();
    const deltaX = moveEvt.clientX - startX;
    const deltaY = moveEvt.clientY - startY;

    let newWidth = startWidth;
    let newHeight = startHeight;

    if (handle.includes('r')) newWidth = startWidth + deltaX;
    if (handle.includes('l')) newWidth = startWidth - deltaX;
    if (handle.includes('b')) newHeight = startHeight + deltaY;
    if (handle.includes('t')) newHeight = startHeight - deltaY;

    const minW = 380;
    const maxW = window.innerWidth * 0.98;
    const minH = 250;
    const maxH = window.innerHeight * 0.96;

    newWidth = Math.max(minW, Math.min(maxW, newWidth));
    newHeight = Math.max(minH, Math.min(maxH, newHeight));

    win.style.width = `${newWidth}px`;
    win.style.maxWidth = 'none';
    win.style.height = `${newHeight}px`;
    win.style.maxHeight = 'none';
  }

  function onMouseUp() {
    win.style.transition = origTransition || '';
    document.removeEventListener('mousemove', onMouseMove);
    document.removeEventListener('mouseup', onMouseUp);
  }

  document.addEventListener('mousemove', onMouseMove);
  document.addEventListener('mouseup', onMouseUp);
}

// ==========================================
// 20. EXPORTAÇÃO E IMPRESSÃO DE RESULTADOS DE PESQUISA (PDF & EXCEL)
// ==========================================

function getFilteredClientesList() {
  const query = document.getElementById('clientPageSearchQuery')?.value.trim() || '';
  let list = [...(db.clientes || [])];
  if (query) {
    const qNorm = typeof normalizeText === 'function' ? normalizeText(query) : query.toLowerCase();
    list = list.filter(cli => {
      const norm = (str) => typeof normalizeText === 'function' ? normalizeText(str || '') : (str || '').toLowerCase();
      return (
        norm(cli.nome).includes(qNorm) ||
        norm(cli.contribuinte).includes(qNorm) ||
        norm(cli.localidade).includes(qNorm) ||
        norm(cli.direcao1).includes(qNorm) ||
        norm(cli.email).includes(qNorm) ||
        norm(cli.telefone).includes(qNorm) ||
        norm(cli.telemovel).includes(qNorm) ||
        norm(cli.tipoCliente).includes(qNorm) ||
        norm(cli.ministerio).includes(qNorm)
      );
    });
  }
  list.sort((a, b) => (a.nome || '').localeCompare(b.nome || '', 'pt', { sensitivity: 'base' }));
  return { list, query };
}

function getFilteredContactosList() {
  const query = document.getElementById('contactPageSearchQuery')?.value.trim() || '';
  let list = [...(db.contactos || [])];
  if (query) {
    const qNorm = typeof normalizeText === 'function' ? normalizeText(query) : query.toLowerCase();
    list = list.filter(con => {
      const client = db.clientes.find(c => c.id === con.clienteId);
      const clientName = client ? (typeof normalizeText === 'function' ? normalizeText(client.nome) : client.nome.toLowerCase()) : '';
      const norm = (str) => typeof normalizeText === 'function' ? normalizeText(str || '') : (str || '').toLowerCase();
      return (
        norm(con.nome).includes(qNorm) ||
        norm(con.apelido).includes(qNorm) ||
        norm(con.cargo).includes(qNorm) ||
        norm(con.email).includes(qNorm) ||
        norm(con.telefone).includes(qNorm) ||
        norm(con.telemovel).includes(qNorm) ||
        norm(con.notas).includes(qNorm) ||
        clientName.includes(qNorm)
      );
    });
  }
  list.sort((a, b) => {
    const nameA = `${a.nome || ''} ${a.apelido || ''}`.trim();
    const nameB = `${b.nome || ''} ${b.apelido || ''}`.trim();
    return nameA.localeCompare(nameB, 'pt', { sensitivity: 'base' });
  });
  return { list, query };
}

function getFilteredProjetosList() {
  const query = document.getElementById('projectPageSearchQuery')?.value.trim() || '';
  let list = [...(db.projetos || [])];
  if (query) {
    const qNorm = typeof normalizeText === 'function' ? normalizeText(query) : query.toLowerCase();
    list = list.filter(p => {
      const client = db.clientes.find(c => c.id === p.clienteId);
      const clientName = client ? (typeof normalizeText === 'function' ? normalizeText(client.nome) : client.nome.toLowerCase()) : '';
      const norm = (str) => typeof normalizeText === 'function' ? normalizeText(str || '') : (str || '').toLowerCase();
      return (
        norm(p.nome).includes(qNorm) ||
        norm(p.tipo).includes(qNorm) ||
        norm(p.estado).includes(qNorm) ||
        norm(p.viatura).includes(qNorm) ||
        norm(p.matricula).includes(qNorm) ||
        clientName.includes(qNorm)
      );
    });
  }
  list.sort((a, b) => (a.nome || '').localeCompare(b.nome || '', 'pt', { sensitivity: 'base' }));
  return { list, query };
}

function exportSearchToPDF(type) {
  let title = '';
  let headers = [];
  let rows = [];

  if (type === 'global') {
    const cat = document.getElementById('searchCategory')?.value || 'clientes';
    const query = document.getElementById('globalSearchQuery')?.value.trim() || '';
    if (cat === 'clientes') {
      if (document.getElementById('clientPageSearchQuery')) document.getElementById('clientPageSearchQuery').value = query;
      type = 'clientes';
    } else if (cat === 'contactos') {
      if (document.getElementById('contactPageSearchQuery')) document.getElementById('contactPageSearchQuery').value = query;
      type = 'contactos';
    } else {
      if (document.getElementById('projectPageSearchQuery')) document.getElementById('projectPageSearchQuery').value = query;
      type = 'projetos';
    }
  }

  if (type === 'clientes') {
    const { list, query } = getFilteredClientesList();
    title = query ? `Resultados da Pesquisa de Clientes ("${query}")` : 'Lista de Clientes Registados';
    headers = [['Tipo', 'Nome / Razão Social', 'Contribuinte (NIF)', 'Telefone / Telemóvel', 'Email', 'Localidade']];
    rows = list.map(c => [
      c.tipoCliente || 'Privado',
      c.nome || '-',
      c.contribuinte || '-',
      c.telemovel || c.telefone || '-',
      c.email || '-',
      c.localidade || '-'
    ]);
  } else if (type === 'contactos') {
    const { list, query } = getFilteredContactosList();
    title = query ? `Resultados da Pesquisa de Contactos ("${query}")` : 'Lista de Contactos Diretos';
    headers = [['Nome do Contacto', 'Cliente Associado', 'Cargo', 'Telemóvel / Telefone', 'Email']];
    rows = list.map(con => {
      const client = db.clientes.find(c => c.id === con.clienteId);
      return [
        `${con.nome || ''} ${con.apelido || ''}`.trim(),
        client ? client.nome : '-',
        con.cargo || '-',
        con.telemovel || con.telefone || '-',
        con.email || '-'
      ];
    });
  } else if (type === 'projetos') {
    const { list, query } = getFilteredProjetosList();
    title = query ? `Resultados da Pesquisa de Projetos ("${query}")` : 'Lista de Projetos Registados';
    headers = [['Nome do Projeto', 'Cliente Associado', 'Tipo', 'Estado', 'Data Início', 'Viatura / Matrícula']];
    rows = list.map(p => {
      const client = db.clientes.find(c => c.id === p.clienteId);
      const vehicle = [p.viatura, p.matricula].filter(Boolean).join(' - ');
      return [
        p.nome || '-',
        client ? client.nome : '-',
        p.tipo || '-',
        p.estado || '-',
        p.dataInicio ? new Date(p.dataInicio).toLocaleDateString('pt-PT') : '-',
        vehicle || '-'
      ];
    });
  }

  if (rows.length === 0) {
    showToast('Nenhum resultado encontrado para imprimir em PDF.', 'warning');
    return;
  }

  if (!window.jspdf || !window.jspdf.jsPDF) {
    showToast('Biblioteca PDF a carregar. Tente novamente.', 'danger');
    return;
  }

  const { jsPDF } = window.jspdf;
  const doc = new jsPDF('landscape');

  doc.setFontSize(15);
  doc.setTextColor(30, 58, 138);
  doc.text(title, 14, 15);

  doc.setFontSize(9);
  doc.setTextColor(100, 116, 139);
  doc.text(`Total de Registos: ${rows.length} | Data da Impressão: ${new Date().toLocaleDateString('pt-PT')}`, 14, 22);

  doc.autoTable({
    startY: 26,
    head: headers,
    body: rows,
    theme: 'grid',
    headStyles: { fillColor: [37, 99, 235], textColor: [255, 255, 255], fontStyle: 'bold' },
    alternateRowStyles: { fillColor: [248, 250, 252] },
    styles: { fontSize: 8, cellPadding: 3 }
  });

  const timestamp = new Date().toISOString().slice(0, 10);
  doc.save(`Pesquisa_${type}_${timestamp}.pdf`);
  showToast('Ficheiro PDF gerado com sucesso!');
}

function exportSearchToExcel(type) {
  let fileName = '';
  let dataObjects = [];

  if (type === 'global') {
    const cat = document.getElementById('searchCategory')?.value || 'clientes';
    const query = document.getElementById('globalSearchQuery')?.value.trim() || '';
    if (cat === 'clientes') {
      if (document.getElementById('clientPageSearchQuery')) document.getElementById('clientPageSearchQuery').value = query;
      type = 'clientes';
    } else if (cat === 'contactos') {
      if (document.getElementById('contactPageSearchQuery')) document.getElementById('contactPageSearchQuery').value = query;
      type = 'contactos';
    } else {
      if (document.getElementById('projectPageSearchQuery')) document.getElementById('projectPageSearchQuery').value = query;
      type = 'projetos';
    }
  }

  if (type === 'clientes') {
    const { list, query } = getFilteredClientesList();
    fileName = query ? `Pesquisa_Clientes_${query.replace(/[^\w-]/g, '_')}` : 'Pesquisa_Clientes';
    dataObjects = list.map(c => ({
      'Tipo Cliente': c.tipoCliente || 'Privado',
      'Nome / Razão Social': c.nome || '',
      'Contribuinte (NIF)': c.contribuinte || '',
      'Telefone': c.telefone || '',
      'Telemóvel': c.telemovel || '',
      'Email': c.email || '',
      'Morada': c.direcao1 || '',
      'Código Postal': c.codigoPostal || '',
      'Localidade': c.localidade || ''
    }));
  } else if (type === 'contactos') {
    const { list, query } = getFilteredContactosList();
    fileName = query ? `Pesquisa_Contactos_${query.replace(/[^\w-]/g, '_')}` : 'Pesquisa_Contactos';
    dataObjects = list.map(con => {
      const client = db.clientes.find(c => c.id === con.clienteId);
      return {
        'Nome Contacto': `${con.nome || ''} ${con.apelido || ''}`.trim(),
        'Cliente Associado': client ? client.nome : '',
        'Cargo': con.cargo || '',
        'Telefone': con.telefone || '',
        'Telemóvel': con.telemovel || '',
        'Email': con.email || '',
        'Notas': con.notas || ''
      };
    });
  } else if (type === 'projetos') {
    const { list, query } = getFilteredProjetosList();
    fileName = query ? `Pesquisa_Projetos_${query.replace(/[^\w-]/g, '_')}` : 'Pesquisa_Projetos';
    dataObjects = list.map(p => {
      const client = db.clientes.find(c => c.id === p.clienteId);
      return {
        'Nome Projeto': p.nome || '',
        'Cliente Associado': client ? client.nome : '',
        'Tipo Projeto': p.tipo || '',
        'Estado': p.estado || '',
        'Data Início': p.dataInicio || '',
        'Data Fim': p.dataFim || '',
        'Viatura': p.viatura || '',
        'Matrícula': p.matricula || ''
      };
    });
  }

  if (dataObjects.length === 0) {
    showToast('Nenhum resultado encontrado para exportar em Excel.', 'warning');
    return;
  }

  if (typeof XLSX === 'undefined') {
    showToast('Biblioteca Excel a carregar. Tente novamente.', 'danger');
    return;
  }

  const worksheet = XLSX.utils.json_to_sheet(dataObjects);
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, 'Pesquisa');

  const timestamp = new Date().toISOString().slice(0, 10);
  XLSX.writeFile(workbook, `${fileName}_${timestamp}.xlsx`);
  showToast('Ficheiro Excel (.xlsx) gerado com sucesso!');
}

