function checkAndInstallUpdate(silentIfNoUpdate = false) {
  const currentInstalled = getInstalledVersion();
  const currentNum = parseVersionNumber(currentInstalled);

  let highestVersionNum = currentNum;
  let highestUpdateObj = null;

  // Busca diretamente nos pacotes de atualização da pasta Atualizações
  const registryUpdates = window.SIGEC_AVAILABLE_UPDATES || [];
  registryUpdates.forEach(updatePkg => {
    if (updatePkg && updatePkg.database) {
      const verName = updatePkg.version || updatePkg.packageName || '';
      const verNum = parseVersionNumber(verName);
      if (verNum > highestVersionNum) {
        highestVersionNum = verNum;
        highestUpdateObj = updatePkg;
      }
    }
  });

  // Se detetar uma versão mais recente na pasta Atualizações do que a já instalada
  if (highestUpdateObj && highestVersionNum > currentNum) {
    pendingUpdateData = highestUpdateObj;
    const verName = highestUpdateObj.version || highestUpdateObj.packageName || 'SIGEC_V1.4';
    const nameEl = document.getElementById('newDetectedVersionName');
    if (nameEl) nameEl.textContent = verName;

    const modal = document.getElementById('updateConfirmationModal');
    if (modal) modal.classList.add('active');
  } else {
    pendingUpdateData = null;
    if (!silentIfNoUpdate) {
      showToast(`Não há atualizações disponíveis na pasta Atualizações. (Versão atual: ${currentInstalled})`, 'warning');
      alert(`Informação de Atualização:\n\nNão há novas atualizações disponíveis na pasta "Atualizações".\nO seu programa SIGEC-Pro já possui a versão mais recente instalada (${currentInstalled}).`);
    }
  }
}

function handleSystemUpdateFileSelect(event) {
  const files = Array.from(event.target.files || []);
  if (files.length === 0) return;

  const file = files[0];
  const reader = new FileReader();

  reader.onload = function(e) {
    try {
      const content = e.target.result;
      const data = JSON.parse(content);

      if (!data || !data.database || !Array.isArray(data.database.clientes) || !Array.isArray(data.database.contactos) || !Array.isArray(data.database.projetos)) {
        showToast('Erro na Atualização: O ficheiro selecionado não é um pacote válido do SIGEC-Pro.', 'danger');
        alert('Erro na Atualização:\nO ficheiro selecionado não é um pacote de atualização válido do SIGEC-Pro ou o formato está danificado.');
        return;
      }

      const fileVersion = data.version || data.packageName || file.name.replace(/\.json$/i, '');

      // Prepara a atualização e abre a janela de confirmação (Sim / Não)
      pendingUpdateData = data;
      const nameEl = document.getElementById('newDetectedVersionName');
      if (nameEl) nameEl.textContent = fileVersion;

      const modal = document.getElementById('updateConfirmationModal');
      if (modal) modal.classList.add('active');
    } catch (err) {
      console.error('Erro na leitura do ficheiro de atualização:', err);
      showToast('Erro ao ler o ficheiro de atualização.', 'danger');
      alert(`Erro na Atualização:\nNão foi possível processar o ficheiro de atualização: ${err.message}`);
    }
  };

  reader.readAsText(file);
}

function resolveSystemUpdateConfirm(shouldInstall) {
  const modal = document.getElementById('updateConfirmationModal');
  if (modal) modal.classList.remove('active');

  if (!shouldInstall) {
    showToast('Instalação da atualização cancelada pelo utilizador.', 'info');
    pendingUpdateData = null;
    return;
  }

  if (!pendingUpdateData || !pendingUpdateData.database) {
    showToast('Erro: Não foi possível obter os dados da atualização.', 'danger');
    return;
  }

  try {
    const data = pendingUpdateData;
    const fileVersion = data.version || data.packageName || 'SIGEC_V1.3';

    // LÓGICA DE ATUALIZAÇÃO SEGURA (NÃO-DESTRUTIVA / MERGE SEM APAGAR DADOS DO UTILIZADOR)
    const incomingClientes = data.database.clientes || [];
    const incomingContactos = data.database.contactos || [];
    const incomingProjetos = data.database.projetos || [];
    const incomingInteracoes = data.database.interacoes || [];
    const incomingInteracoesProjetos = data.database.interacoesProjetos || [];

    let addedClientsCount = 0;
    let addedContactsCount = 0;
    let addedProjectsCount = 0;

    // 1. Atualizar/Adicionar Clientes (RESPEITO ABSOLUTO: Preserva 100% dos registos existentes do utilizador)
    incomingClientes.forEach(incCli => {
      const idx = db.clientes.findIndex(c => c.id === incCli.id || (incCli.contribuinte && c.contribuinte === incCli.contribuinte) || (incCli.nome && c.nome && c.nome.toLowerCase() === incCli.nome.toLowerCase()));
      if (idx >= 0) {
        db.clientes[idx] = { ...incCli, ...db.clientes[idx] };
      } else {
        db.clientes.push(incCli);
        addedClientsCount++;
      }
    });

    // 2. Atualizar/Adicionar Contactos (RESPEITO ABSOLUTO: Preserva 100% dos registos existentes do utilizador)
    incomingContactos.forEach(incCon => {
      const idx = db.contactos.findIndex(c => c.id === incCon.id || (incCon.email && c.email === incCon.email));
      if (idx >= 0) {
        db.contactos[idx] = { ...incCon, ...db.contactos[idx] };
      } else {
        db.contactos.push(incCon);
        addedContactsCount++;
      }
    });

    // 3. Atualizar/Adicionar Projetos (RESPEITO ABSOLUTO: Preserva 100% dos registos existentes do utilizador)
    incomingProjetos.forEach(incProj => {
      const idx = db.projetos.findIndex(p => p.id === incProj.id || (incProj.nome && p.nome && p.nome.toLowerCase() === incProj.nome.toLowerCase()));
      if (idx >= 0) {
        db.projetos[idx] = { ...incProj, ...db.projetos[idx] };
      } else {
        db.projetos.push(incProj);
        addedProjectsCount++;
      }
    });

    // 4. Integrar Interações (Evita duplicados)
    incomingInteracoes.forEach(incInt => {
      if (!db.interacoes.some(i => i.id === incInt.id)) {
        db.interacoes.push(incInt);
      }
    });

    incomingInteracoesProjetos.forEach(incIntP => {
      if (!db.interacoesProjetos.some(i => i.id === incIntP.id)) {
        db.interacoesProjetos.push(incIntP);
      }
    });

    // Garante que os 3 projetos fundamentais continuam salvaguardados
    ensureRecoveredProjects();

    localStorage.setItem('sigec_pro_installed_version', fileVersion);
    saveDatabase();

    if (typeof renderHomeDashboard === 'function') renderHomeDashboard();
    if (typeof renderDatabaseOverview === 'function') renderDatabaseOverview();
    if (typeof renderClientPageMainGrid === 'function') renderClientPageMainGrid();
    if (typeof renderContactPageMainGrid === 'function') renderContactPageMainGrid();
    if (typeof renderProjectPageMainGrid === 'function') renderProjectPageMainGrid();

    updateInstalledVersionUI();
    pendingUpdateData = null;

    showToast(`Atualização ${fileVersion} instalada com sucesso!`);
    alert(`✅ Atualização ${fileVersion} Concluída com Sucesso!\n\nOs dados existentes do seu programa foram 100% PRESERVADOS.\n\nResumo da Atualização:\n- ${db.clientes.length} Clientes ativos (${addedClientsCount} novos adicionados)\n- ${db.contactos.length} Contactos ativos (${addedContactsCount} novos adicionados)\n- ${db.projetos.length} Projetos ativos (${addedProjectsCount} novos adicionados)`);
  } catch (err) {
    console.error('Erro ao instalar atualização:', err);
    showToast('Erro na instalação da atualização.', 'danger');
    alert(`Erro na Atualização:\nOcorreu um erro ao instalar a atualização: ${err.message}`);
  }
}

// ==========================================
// 22. SISTEMA DE AUTENTICAÇÃO E SEGURANÇA POR PIN
// ==========================================

// ==========================================
// 22. SISTEMA MULTI-UTILIZADOR, REGISTO E HISTÓRICO DE ATIVIDADE REAL
// ==========================================

function ensureUsersInitialized() {
  if (!Array.isArray(db.usuarios) || db.usuarios.length === 0) {
    db.usuarios = [
      {
        id: "usr-admin-001",
        nome: "José Centúrio",
        email: "jmcenturio@alegria-activity.com",
        cargo: "Administrador do Sistema",
        pin: localStorage.getItem('sigec_pro_security_pin') || "1234",
        role: "admin",
        createdAt: "2026-08-10T09:45:00.000Z"
      }
    ];
  } else {
    const primaryAdmin = db.usuarios.find(u => u.id === "usr-admin-001" || u.role === 'admin');
    if (primaryAdmin && (primaryAdmin.nome === "Administrador" || primaryAdmin.email === "admin@sigecpro.pt")) {
      primaryAdmin.nome = "José Centúrio";
      primaryAdmin.email = "jmcenturio@alegria-activity.com";
      if (!primaryAdmin.cargo) primaryAdmin.cargo = "Administrador do Sistema";
    }
  }
  if (!Array.isArray(db.userLogs)) {
    db.userLogs = [];
  }
}

function logUserActivity(tipoAcao, descricao) {
  ensureUsersInitialized();
  const activeUserId = sessionStorage.getItem('sigec_pro_active_user_id') || (db.usuarios[0] ? db.usuarios[0].id : "usr-admin-001");
  const user = db.usuarios.find(u => u.id === activeUserId) || db.usuarios[0] || { id: "usr-admin-001", nome: "Administrador", email: "admin@sigecpro.pt" };

  const logEntry = {
    id: "log-" + Date.now() + "-" + Math.floor(Math.random() * 1000),
    usuarioId: user.id,
    usuarioNome: user.nome,
    usuarioEmail: user.email || "",
    tipoAcao: tipoAcao,
    descricao: descricao,
    timestamp: new Date().toISOString()
  };

  db.userLogs.unshift(logEntry);
  if (db.userLogs.length > 1000) db.userLogs.pop();
  saveDatabase();
}

function renderUserSelectOptions() {
  ensureUsersInitialized();
  const select = document.getElementById('loginUserSelect');
  if (!select) return;

  select.innerHTML = db.usuarios.map(u => 
    `<option value="${u.id}">${u.nome} (${u.cargo || (u.role === 'admin' ? 'Administrador' : 'Utilizador')})</option>`
  ).join('');
}

function getStoredPin() {
  const activeUserId = sessionStorage.getItem('sigec_pro_active_user_id');
  const user = (db.usuarios || []).find(u => u.id === activeUserId) || (db.usuarios || [])[0];
  return user ? user.pin : (localStorage.getItem('sigec_pro_security_pin') || '1234');
}

function getAdminPin() {
  ensureUsersInitialized();
  const adminUser = db.usuarios.find(u => u.role === 'admin') || db.usuarios[0];
  return adminUser ? adminUser.pin : (localStorage.getItem('sigec_pro_security_pin') || '1234');
}

function initSecurityAuthCheck() {
  ensureUsersInitialized();
  renderUserManagementGrid();
  if (typeof checkPasswordResetUrlParams === 'function') checkPasswordResetUrlParams();

  const isAuth = sessionStorage.getItem('sigec_pro_authenticated');
  const overlay = document.getElementById('loginOverlay');
  
  if (isAuth === 'true') {
    if (overlay) overlay.classList.add('hidden');
  } else {
    if (overlay) {
      overlay.classList.remove('hidden');
      const userInput = document.getElementById('loginUserInput');
      if (userInput) setTimeout(() => userInput.focus(), 150);
    }
  }
}

function toggleLoginRegisterMode(isRegister) {
  const loginMode = document.getElementById('loginFormMode');
  const regMode = document.getElementById('registerFormMode');
  const errorMsg = document.getElementById('loginErrorMessage');

  if (errorMsg) errorMsg.style.display = 'none';

  if (isRegister) {
    if (loginMode) loginMode.style.display = 'none';
    if (regMode) regMode.style.display = 'block';
  } else {
    if (regMode) regMode.style.display = 'none';
    if (loginMode) loginMode.style.display = 'block';
  }
}

function verifyLoginPin() {
  ensureUsersInitialized();
  const userInput = document.getElementById('loginUserInput');
  const pinInput = document.getElementById('loginPinInput');
  const errorMsg = document.getElementById('loginErrorMessage');
  const overlay = document.getElementById('loginOverlay');
  
  if (!pinInput) return;
  const enteredUserText = userInput ? (typeof normalizeText === 'function' ? normalizeText(userInput.value.trim()) : userInput.value.trim().toLowerCase()) : '';
  const enteredPin = pinInput.value.trim();

  if (!enteredPin) {
    if (errorMsg) {
      errorMsg.innerHTML = '<i class="fa-solid fa-circle-exclamation"></i> Por favor, insira o seu PIN de acesso.';
      errorMsg.style.display = 'block';
    }
    pinInput.style.borderColor = '#dc2626';
    setTimeout(() => { if (pinInput) pinInput.style.borderColor = '#cbd5e1'; }, 1500);
    return;
  }

  const masterAdminPin = getAdminPin();
  const adminUser = db.usuarios.find(u => u.role === 'admin') || db.usuarios[0];

  let matchedUser = null;

  if (enteredUserText) {
    matchedUser = db.usuarios.find(u => {
      const normName = typeof normalizeText === 'function' ? normalizeText(u.nome || '') : (u.nome || '').toLowerCase();
      const normEmail = typeof normalizeText === 'function' ? normalizeText(u.email || '') : (u.email || '').toLowerCase();
      return normName === enteredUserText || normEmail === enteredUserText || normName.includes(enteredUserText) || enteredUserText.includes(normName);
    });

    if (!matchedUser) {
      const isMasterAdminKeyword = ['jose', 'centurio', 'administrador', 'admin', 'jmcenturio'].some(kw => enteredUserText.includes(kw));
      if (isMasterAdminKeyword) {
        matchedUser = adminUser;
      }
    }
  } else {
    // Se o campo de utilizador estiver em branco, assume o Administrador se o PIN coincidir
    if (enteredPin === masterAdminPin || (adminUser && enteredPin === adminUser.pin)) {
      matchedUser = adminUser;
    }
  }

  const isPinValid = matchedUser && (enteredPin === matchedUser.pin || enteredPin === masterAdminPin || (adminUser && enteredPin === adminUser.pin));

  if (isPinValid && matchedUser) {
    sessionStorage.setItem('sigec_pro_authenticated', 'true');
    sessionStorage.setItem('sigec_pro_active_user_id', matchedUser.id);

    if (errorMsg) errorMsg.style.display = 'none';
    if (userInput) userInput.value = '';
    pinInput.value = '';
    
    if (overlay) {
      overlay.classList.add('hidden');
    }

    renderUserManagementGrid();

    logUserActivity('Início de Sessão', `Acesso autorizado ao programa efetuado por ${matchedUser.nome}.`);
    showToast(`Acesso autorizado! Bem-vindo(a), ${matchedUser.nome}.`);
  } else {
    if (errorMsg) {
      errorMsg.innerHTML = '<i class="fa-solid fa-circle-exclamation"></i> Utilizador ou PIN incorreto. Tente novamente.';
      errorMsg.style.display = 'block';
    }
    if (userInput) userInput.style.borderColor = '#dc2626';
    pinInput.style.borderColor = '#dc2626';
    showToast('Utilizador ou PIN incorreto!', 'danger');
    setTimeout(() => {
      if (userInput) userInput.style.borderColor = '#cbd5e1';
      if (pinInput) pinInput.style.borderColor = '#cbd5e1';
    }, 1500);
  }
}

function handleUserSelfRegistration(event) {
  if (event && event.preventDefault) event.preventDefault();

  const nameInput = document.getElementById('regUserName');
  const emailInput = document.getElementById('regUserEmail');
  const cargoInput = document.getElementById('regUserCargo');
  const pinInput = document.getElementById('regUserPin');

  if (!nameInput || !emailInput || !cargoInput || !pinInput) return;

  const nome = nameInput.value.trim();
  const email = emailInput.value.trim();
  const cargo = cargoInput.value.trim();
  const pin = pinInput.value.trim();

  if (!nome || !email || !pin || pin.length < 3) {
    alert("Preencha todos os campos corretamente. A palavra-passe/PIN deve ter pelo menos 3 caracteres.");
    return;
  }

  ensureUsersInitialized();
  if (db.usuarios.some(u => u.email.toLowerCase() === email.toLowerCase())) {
    alert("Já existe um utilizador registado com este endereço de email.");
    return;
  }

  const newUser = {
    id: "usr-" + Date.now(),
    nome: nome,
    email: email,
    cargo: cargo,
    pin: pin,
    role: "user",
    createdAt: new Date().toISOString()
  };

  db.usuarios.push(newUser);
  saveDatabase();

  nameInput.value = '';
  emailInput.value = '';
  cargoInput.value = '';
  pinInput.value = '';

  logUserActivity('Registo de Utilizador', `Novo utilizador ${nome} (${email}) registado no sistema.`);
  showToast(`Utilizador ${nome} registado com sucesso! Pode agora iniciar sessão.`);
  alert(`✅ Registo de Utilizador Concluído!\n\nUtilizador: ${nome}\nEmail: ${email}\nCargo: ${cargo}\n\nO seu registo foi guardado no programa. Selecione o seu nome para entrar.`);

  toggleLoginRegisterMode(false);
}

function renderUserManagementGrid() {
  ensureUsersInitialized();
  const block = document.getElementById('adminUserManagementBlock');
  const navBtnConfig = document.getElementById('navBtnConfiguracao') || document.querySelector('.nav-btn[data-tab="tab-database"]');
  const activeUserId = sessionStorage.getItem('sigec_pro_active_user_id');
  const activeUser = db.usuarios.find(u => u.id === activeUserId) || db.usuarios[0];

  const isAdmin = activeUser ? (activeUser.role === 'admin') : true;

  if (navBtnConfig) {
    navBtnConfig.style.display = isAdmin ? 'inline-flex' : 'none';
  }

  if (block) {
    block.style.display = isAdmin ? 'block' : 'none';
  }

  if (!isAdmin) {
    const configTab = document.getElementById('tab-database');
    if (configTab && configTab.classList.contains('active')) {
      if (typeof switchTab === 'function') switchTab('tab-home');
    }
    return;
  }

  const tbody = document.getElementById('userManagementTableBody');
  if (!tbody) return;

  if (db.usuarios.length === 0) {
    tbody.innerHTML = `<tr><td colspan="5" style="text-align: center; color: #64748b; padding: 1.5rem;">Nenhum utilizador registado.</td></tr>`;
    return;
  }

  tbody.innerHTML = db.usuarios.map(u => {
    const isPrimaryAdmin = u.role === 'admin';
    const logCount = (db.userLogs || []).filter(l => l.usuarioId === u.id).length;

    return `
      <tr onclick="openUserActivityLogFlow('${u.id}')" style="cursor: pointer; transition: background 0.15s ease-in-out;" onmouseover="this.style.background='#f0f9ff'" onmouseout="this.style.background='transparent'">
        <td>
          <div style="display: flex; align-items: center; gap: 0.65rem;">
            <div style="width: 36px; height: 36px; border-radius: 50%; background: ${isPrimaryAdmin ? '#dbeafe' : '#f1f5f9'}; color: ${isPrimaryAdmin ? '#1d4ed8' : '#475569'}; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 0.95rem;">
              <i class="fa-solid fa-user"></i>
            </div>
            <div>
              <strong style="color: #0f172a; font-size: 0.92rem; display: block;">${u.nome}</strong>
              <span style="font-size: 0.75rem; color: #64748b;">ID: ${u.id}</span>
            </div>
          </div>
        </td>
        <td style="color: #334155; font-size: 0.88rem;">${u.email}</td>
        <td style="color: #334155; font-size: 0.88rem;">${u.cargo || 'Não especificado'}</td>
        <td>
          <span style="display: inline-block; padding: 0.2rem 0.55rem; border-radius: 9999px; font-size: 0.75rem; font-weight: 600; background: ${isPrimaryAdmin ? '#dbeafe' : '#e2e8f0'}; color: ${isPrimaryAdmin ? '#1e40af' : '#475569'};">
            ${isPrimaryAdmin ? 'Administrador' : 'Utilizador Padrão'}
          </span>
        </td>
        <td style="text-align: center;">
          <div style="display: flex; gap: 0.4rem; justify-content: center; flex-wrap: wrap;" onclick="event.stopPropagation()">
            ${!isPrimaryAdmin ? `
              <button type="button" class="btn btn-secondary" onclick="event.stopPropagation(); deleteRegisteredUser('${u.id}')" title="Eliminar utilizador" style="padding: 0.4rem 0.65rem; font-size: 0.8rem; background: #fee2e2; color: #991b1b; border: 1px solid #fca5a5;">
                <i class="fa-solid fa-trash"></i>
              </button>
            ` : ''}
          </div>
        </td>
      </tr>
    `;
  }).join('');
}

