let pendingTargetProfileUserId = null;

function openUserActivityLogFlow(userId) {
  pendingTargetProfileUserId = userId;
  const adminModal = document.getElementById('adminAuthModal');
  const pinInput = document.getElementById('adminAuthPinInput');
  
  if (pinInput) pinInput.value = '';
  if (adminModal) adminModal.classList.add('active');
}

function closeAdminAuthModal() {
  const adminModal = document.getElementById('adminAuthModal');
  if (adminModal) adminModal.classList.remove('active');
  pendingTargetProfileUserId = null;
}

function confirmAdminAuthForActivityLog(event) {
  if (event && event.preventDefault) event.preventDefault();

  const pinInput = document.getElementById('adminAuthPinInput');
  if (!pinInput || !pendingTargetProfileUserId) return;

  const enteredPin = pinInput.value.trim();
  const adminPin = getAdminPin();

  if (enteredPin !== adminPin) {
    showToast('Erro: Palavra-passe/PIN de Administrador incorreto.', 'danger');
    alert('Acesso Negado:\nA palavra-passe de Administrador introduzida não está correta.');
    return;
  }

  const targetUserId = pendingTargetProfileUserId;
  closeAdminAuthModal();
  openUserProfileModal(targetUserId, 'info');
}

function openUserProfileModal(userId, initialTab = 'info') {
  ensureUsersInitialized();
  const user = db.usuarios.find(u => u.id === userId);
  if (!user) return;

  pendingTargetProfileUserId = userId;

  const modal = document.getElementById('userProfileModal');
  const title = document.getElementById('userProfileModalTitle');
  const badge = document.getElementById('userProfileBadge');

  if (title) title.textContent = `Ficha do Utilizador - ${user.nome}`;
  if (badge) badge.textContent = user.role === 'admin' ? 'Administrador do Sistema' : 'Utilizador Padrão';

  // Fill Tab 1 Info
  const idInput = document.getElementById('profileUserId');
  const nameInput = document.getElementById('profileUserName');
  const emailInput = document.getElementById('profileUserEmail');
  const cargoInput = document.getElementById('profileUserCargo');
  const roleSelect = document.getElementById('profileUserRole');
  const pinInput = document.getElementById('profileUserPin');

  if (idInput) idInput.value = user.id;
  if (nameInput) nameInput.value = user.nome || '';
  if (emailInput) emailInput.value = user.email || '';
  if (cargoInput) cargoInput.value = user.cargo || '';
  if (roleSelect) roleSelect.value = user.role || 'user';
  if (pinInput) pinInput.value = user.pin || '';

  // Reset Date Filter to 'all'
  const filterSelect = document.getElementById('userActivityDateRange');
  const customDateInput = document.getElementById('userActivityCustomDate');
  if (filterSelect) filterSelect.value = 'all';
  if (customDateInput) {
    customDateInput.value = '';
    customDateInput.style.display = 'none';
  }

  switchUserProfileTab(initialTab);

  if (modal) modal.classList.add('active');
  logUserActivity('Ficha do Utilizador', `Ficha do utilizador ${user.nome} aberta após autenticação de Administrador.`);
}

function closeUserProfileModal() {
  const modal = document.getElementById('userProfileModal');
  if (modal) modal.classList.remove('active');
  pendingTargetProfileUserId = null;
}

function switchUserProfileTab(tabName) {
  const tabInfo = document.getElementById('userProfileTabInfo');
  const tabActivity = document.getElementById('userProfileTabActivity');
  const btnInfo = document.getElementById('tabBtnUserProfileInfo');
  const btnActivity = document.getElementById('tabBtnUserProfileActivity');

  if (tabName === 'info') {
    if (tabInfo) tabInfo.style.display = 'block';
    if (tabActivity) tabActivity.style.display = 'none';
    if (btnInfo) {
      btnInfo.style.borderBottomColor = '#38bdf8';
      btnInfo.style.color = '#ffffff';
      btnInfo.style.fontWeight = '700';
    }
    if (btnActivity) {
      btnActivity.style.borderBottomColor = 'transparent';
      btnActivity.style.color = '#94a3b8';
      btnActivity.style.fontWeight = '600';
    }
  } else {
    if (tabInfo) tabInfo.style.display = 'none';
    if (tabActivity) tabActivity.style.display = 'block';
    if (btnActivity) {
      btnActivity.style.borderBottomColor = '#38bdf8';
      btnActivity.style.color = '#ffffff';
      btnActivity.style.fontWeight = '700';
    }
    if (btnInfo) {
      btnInfo.style.borderBottomColor = 'transparent';
      btnInfo.style.color = '#94a3b8';
      btnInfo.style.fontWeight = '600';
    }
    renderUserProfileActivityTimeline();
  }
}

function handleSaveUserProfile(event) {
  if (event && event.preventDefault) event.preventDefault();

  const idInput = document.getElementById('profileUserId');
  const nameInput = document.getElementById('profileUserName');
  const emailInput = document.getElementById('profileUserEmail');
  const cargoInput = document.getElementById('profileUserCargo');
  const roleSelect = document.getElementById('profileUserRole');
  const pinInput = document.getElementById('profileUserPin');

  if (!idInput || !nameInput || !emailInput || !cargoInput || !roleSelect || !pinInput) return;

  const userId = idInput.value;
  const nome = nameInput.value.trim();
  const email = emailInput.value.trim();
  const cargo = cargoInput.value.trim();
  const role = roleSelect.value;
  const pin = pinInput.value.trim();

  if (!nome || !email || !pin || pin.length < 3) {
    alert("Preencha todos os campos. O PIN deve ter pelo menos 3 caracteres.");
    return;
  }

  ensureUsersInitialized();
  const userIndex = db.usuarios.findIndex(u => u.id === userId);
  if (userIndex < 0) return;

  if (db.usuarios.some((u, idx) => idx !== userIndex && u.email.toLowerCase() === email.toLowerCase())) {
    alert("Já existe outro utilizador registado com este email.");
    return;
  }

  db.usuarios[userIndex] = {
    ...db.usuarios[userIndex],
    nome: nome,
    email: email,
    cargo: cargo,
    role: role,
    pin: pin
  };

  if (role === 'admin') {
    localStorage.setItem('sigec_pro_security_pin', pin);
  }

  saveDatabase();
  renderUserManagementGrid();
  renderUserSelectOptions();

  logUserActivity('Ficha do Utilizador', `Dados de registo e PIN do utilizador ${nome} atualizados com sucesso.`);
  showToast(`Ficha do utilizador ${nome} atualizada com sucesso!`);
  alert(`✅ Ficha Atualizada!\n\nOs dados de registo e o PIN do utilizador "${nome}" foram guardados no programa com sucesso.`);
}

function sendPasswordResetEmailToUser() {
  ensureUsersInitialized();
  const nameInput = document.getElementById('profileUserName');
  const emailInput = document.getElementById('profileUserEmail');
  const idInput = document.getElementById('profileUserId');

  if (!emailInput || !emailInput.value.trim()) {
    alert("Por favor, insira um endereço de email válido na ficha do utilizador.");
    return;
  }

  const adminUser = db.usuarios.find(u => u.role === 'admin') || db.usuarios[0];
  const adminEmail = adminUser ? adminUser.email : 'jmcenturio@alegria-activity.com';
  const adminName = adminUser ? adminUser.nome : 'Administrador do Sistema';

  const userEmail = emailInput.value.trim();
  const userName = nameInput ? nameInput.value.trim() : 'Utilizador';
  const userId = idInput ? idInput.value : '';

  const baseUrl = window.location.origin + window.location.pathname;
  const resetToken = "rst-" + Date.now() + "-" + Math.floor(Math.random() * 10000);
  const resetLink = `${baseUrl}?resetToken=${resetToken}&userId=${encodeURIComponent(userId)}`;

  const subject = encodeURIComponent(`[SIGEC-Pro] Alteração de Palavra-passe / PIN - ${userName}`);
  const body = encodeURIComponent(
    `Olá ${userName},\n\n` +
    `O Administrador do Sistema (${adminName} - ${adminEmail}) enviou-lhe esta mensagem para redefinição da sua palavra-passe / PIN de acesso ao programa SIGEC-Pro.\n\n` +
    `Para redefinir o seu PIN de acesso com segurança, por favor clique no link abaixo:\n\n` +
    `${resetLink}\n\n` +
    `Remetente (Administrador): ${adminName} (${adminEmail})\n` +
    `Destinatário: ${userName} (${userEmail})\n\n` +
    `Com os melhores cumprimentos,\n` +
    `SIGEC-Pro - Gestão Empresarial`
  );

  window.open(`mailto:${userEmail}?subject=${subject}&body=${body}`, '_blank');

  logUserActivity('Segurança', `Email de redefinição de palavra-passe enviado de ${adminEmail} para ${userEmail}.`);
  showToast(`Email de recuperação preparado de ${adminEmail} para ${userEmail}!`);
  alert(
    `✅ Email de Recuperação Preparado!\n\n` +
    `Remetente (Administrador): ${adminName} (${adminEmail})\n` +
    `Destinatário: ${userName} (${userEmail})\n\n` +
    `Foi aberto o cliente de email a partir da conta do Administrador (${adminEmail}) com a mensagem e o link de segurança pré-preenchidos.\n\n` +
    `Link de Redefinição Gerado:\n${resetLink}`
  );
}

function openResetPasswordModalFromParams(userId, token) {
  ensureUsersInitialized();
  const user = db.usuarios.find(u => u.id === userId);
  if (!user) return;

  const modal = document.getElementById('resetPasswordModal');
  const info = document.getElementById('resetPasswordUserInfo');
  const userIdEl = document.getElementById('resetPasswordUserId');
  const tokenEl = document.getElementById('resetPasswordToken');
  const pinInput = document.getElementById('resetPasswordNewPin');
  const confirmInput = document.getElementById('resetPasswordConfirmPin');

  if (info) {
    info.innerHTML = `
      <div style="font-weight: 700; color: #0f172a; margin-bottom: 0.2rem;">${user.nome}</div>
      <div>Email registado: <strong>${user.email}</strong></div>
      <div style="font-size: 0.78rem; color: #64748b; margin-top: 0.25rem;">Insira a sua nova palavra-passe / PIN de acesso nos campos abaixo.</div>
    `;
  }

  if (userIdEl) userIdEl.value = user.id;
  if (tokenEl) tokenEl.value = token;
  if (pinInput) pinInput.value = '';
  if (confirmInput) confirmInput.value = '';

  if (modal) modal.classList.add('active');
}

function closeResetPasswordModal() {
  const modal = document.getElementById('resetPasswordModal');
  if (modal) modal.classList.remove('active');
}

function handleSaveResetPasswordFromToken(event) {
  if (event && event.preventDefault) event.preventDefault();

  const userIdEl = document.getElementById('resetPasswordUserId');
  const pinInput = document.getElementById('resetPasswordNewPin');
  const confirmInput = document.getElementById('resetPasswordConfirmPin');

  if (!userIdEl || !pinInput || !confirmInput) return;

  const userId = userIdEl.value;
  const newPin = pinInput.value.trim();
  const confirmPin = confirmInput.value.trim();

  if (!newPin || newPin.length < 3) {
    alert("O novo PIN deve ter pelo menos 3 caracteres.");
    return;
  }

  if (newPin !== confirmPin) {
    alert("As palavras-passe / PINs introduzidas não coincidem.");
    return;
  }

  ensureUsersInitialized();
  const user = db.usuarios.find(u => u.id === userId);
  if (user) {
    user.pin = newPin;
    if (user.role === 'admin') {
      localStorage.setItem('sigec_pro_security_pin', newPin);
    }
    saveDatabase();

    logUserActivity('Segurança', `Palavra-passe / PIN do utilizador ${user.nome} redefinido via link de segurança.`);
    showToast(`Palavra-passe do utilizador ${user.nome} redefinida com sucesso!`);
    alert(`✅ Palavra-passe Atualizada com Sucesso!\n\nA nova palavra-passe / PIN do utilizador "${user.nome}" foi guardada no programa.`);
  }

  closeResetPasswordModal();

  // Clean URL params
  if (window.history && window.history.replaceState) {
    const cleanUrl = window.location.protocol + "//" + window.location.host + window.location.pathname;
    window.history.replaceState({ path: cleanUrl }, '', cleanUrl);
  }
}

function checkPasswordResetUrlParams() {
  try {
    const urlParams = new URLSearchParams(window.location.search);
    if (urlParams.has('resetToken') && urlParams.has('userId')) {
      const resetToken = urlParams.get('resetToken');
      const userId = urlParams.get('userId');
      setTimeout(() => {
        openResetPasswordModalFromParams(userId, resetToken);
      }, 500);
    }
  } catch (e) {
    console.warn('Aviso ao verificar parâmetros de redefinição de password:', e);
  }
}

function handleUserActivityFilterChange() {
  const filterSelect = document.getElementById('userActivityDateRange');
  const customDateInput = document.getElementById('userActivityCustomDate');

  if (!filterSelect || !customDateInput) return;

  if (filterSelect.value === 'custom') {
    customDateInput.style.display = 'inline-block';
  } else {
    customDateInput.style.display = 'none';
  }

  renderUserProfileActivityTimeline();
}

function renderUserProfileActivityTimeline() {
  ensureUsersInitialized();
  const userId = pendingTargetProfileUserId || (document.getElementById('profileUserId') ? document.getElementById('profileUserId').value : null);
  if (!userId) return;

  const user = db.usuarios.find(u => u.id === userId);
  const timeline = document.getElementById('userProfileActivityTimeline');
  if (!timeline) return;

  const filterSelect = document.getElementById('userActivityDateRange');
  const customDateInput = document.getElementById('userActivityCustomDate');
  const rangeMode = filterSelect ? filterSelect.value : 'all';

  let userLogs = (db.userLogs || []).filter(l => l.usuarioId === userId);

  const now = new Date();
  if (rangeMode === 'today') {
    userLogs = userLogs.filter(l => {
      const d = new Date(l.timestamp);
      return d.getFullYear() === now.getFullYear() && d.getMonth() === now.getMonth() && d.getDate() === now.getDate();
    });
  } else if (rangeMode === '7days') {
    const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
    userLogs = userLogs.filter(l => new Date(l.timestamp) >= sevenDaysAgo);
  } else if (rangeMode === '30days') {
    const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
    userLogs = userLogs.filter(l => new Date(l.timestamp) >= thirtyDaysAgo);
  } else if (rangeMode === 'custom' && customDateInput && customDateInput.value) {
    const selectedDateStr = customDateInput.value;
    userLogs = userLogs.filter(l => {
      const d = new Date(l.timestamp);
      const formattedD = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
      return formattedD === selectedDateStr;
    });
  }

  if (userLogs.length === 0) {
    timeline.innerHTML = `
      <div style="padding: 2.5rem 1rem; text-align: center; color: #64748b; background: #f8fafc; border-radius: 8px; border: 1px dashed #cbd5e1;">
        <i class="fa-solid fa-calendar-xmark" style="font-size: 2.2rem; color: #94a3b8; margin-bottom: 0.75rem;"></i>
        <h4 style="margin: 0 0 0.4rem 0; color: #334155;">Sem Atividade para o Período Selecionado</h4>
        <p style="font-size: 0.85rem; margin: 0; color: #64748b;">Nenhum registo de atividade real corresponde ao filtro de data selecionado.</p>
      </div>
    `;
    return;
  }

  timeline.innerHTML = userLogs.map(log => {
    const dateObj = new Date(log.timestamp);
    const formattedDate = `${String(dateObj.getDate()).padStart(2, '0')}-${String(dateObj.getMonth() + 1).padStart(2, '0')}-${dateObj.getFullYear()} ${String(dateObj.getHours()).padStart(2, '0')}:${String(dateObj.getMinutes()).padStart(2, '0')}:${String(dateObj.getSeconds()).padStart(2, '0')}`;

    return `
      <div style="display: flex; gap: 0.85rem; padding: 0.85rem; border-bottom: 1px solid #e2e8f0; align-items: flex-start;">
        <div style="width: 34px; height: 34px; border-radius: 50%; background: #0284c7; color: #ffffff; display: flex; align-items: center; justify-content: center; font-size: 0.85rem; flex-shrink: 0; margin-top: 2px;">
          <i class="fa-solid fa-list-check"></i>
        </div>
        <div style="flex: 1;">
          <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 0.25rem;">
            <span style="font-weight: 700; color: #0369a1; font-size: 0.88rem;">${log.tipoAcao}</span>
            <span style="font-size: 0.76rem; color: #64748b; background: #f1f5f9; padding: 0.15rem 0.55rem; border-radius: 4px; font-weight: 600;">${formattedDate}</span>
          </div>
          <p style="margin: 0; font-size: 0.85rem; color: #334155; line-height: 1.4;">${log.descricao}</p>
        </div>
      </div>
    `;
  }).join('');
}

function deleteRegisteredUser(userId) {
  ensureUsersInitialized();
  const user = db.usuarios.find(u => u.id === userId);
  if (!user) return;

  if (user.role === 'admin') {
    alert("Não é possível eliminar a conta do Administrador principal.");
    return;
  }

  if (confirm(`Tem a certeza que deseja eliminar o utilizador "${user.nome}" (${user.email})?`)) {
    db.usuarios = db.usuarios.filter(u => u.id !== userId);
    saveDatabase();
    renderUserManagementGrid();
    renderUserSelectOptions();

    logUserActivity('Gestão de Utilizadores', `Utilizador ${user.nome} (${user.email}) eliminado do sistema.`);
    showToast(`Utilizador ${user.nome} eliminado com sucesso.`);
  }
}

function lockApplicationScreen() {
  sessionStorage.removeItem('sigec_pro_authenticated');
  sessionStorage.removeItem('sigec_pro_active_user_id');

  const overlay = document.getElementById('loginOverlay');
  const errorMsg = document.getElementById('loginErrorMessage');
  
  if (errorMsg) errorMsg.style.display = 'none';
  if (overlay) {
    overlay.classList.remove('hidden');
    renderUserSelectOptions();
    toggleLoginRegisterMode(false);

    const pinInput = document.getElementById('loginPinInput');
    if (pinInput) {
      pinInput.value = '';
      setTimeout(() => pinInput.focus(), 150);
    }
  }
  showToast('Ecrã de acesso bloqueado com sucesso.', 'info');
}

function changeSystemAccessPin(event) {
  if (event && event.preventDefault) event.preventDefault();

  const currentPinInput = document.getElementById('cfgCurrentPin');
  const newPinInput = document.getElementById('cfgNewPin');

  if (!currentPinInput || !newPinInput) return;

  const currentPin = currentPinInput.value.trim();
  const newPin = newPinInput.value.trim();

  const storedPin = getStoredPin();

  if (currentPin !== storedPin) {
    showToast('Erro: O PIN Atual introduzido está incorreto.', 'danger');
    alert('Erro de Segurança:\nO PIN Atual introduzido não coincide com a palavra-passe do sistema.');
    return;
  }

  if (!newPin || newPin.length < 3) {
    showToast('Erro: O novo PIN deve conter pelo menos 3 caracteres.', 'warning');
    alert('Erro de Validação:\nO novo PIN deve ter pelo menos 3 caracteres.');
    return;
  }

  ensureUsersInitialized();
  const activeUserId = sessionStorage.getItem('sigec_pro_active_user_id') || db.usuarios[0].id;
  const user = db.usuarios.find(u => u.id === activeUserId) || db.usuarios[0];

  if (user) {
    user.pin = newPin;
    if (user.role === 'admin') {
      localStorage.setItem('sigec_pro_security_pin', newPin);
    }
    saveDatabase();
  }

  currentPinInput.value = '';
  newPinInput.value = '';

  logUserActivity('Segurança', `Palavra-passe / PIN de acesso alterado por ${user ? user.nome : 'utilizador'}.`);
  showToast('Palavra-passe / PIN de acesso alterado com sucesso!');
  alert(`✅ Segurança Atualizada com Sucesso!\n\nA sua nova palavra-passe / PIN de acesso foi definida com sucesso.\nGuarde a nova palavra-passe em local seguro.`);
}

document.addEventListener('DOMContentLoaded', function() {
  initSecurityAuthCheck();
});

// ==========================================
// 23. PROTEÇÃO E REPOSIÇÃO DE DADOS COM CONFIRMAÇÃO ESTRITA
// ==========================================

function exportDatabaseJSON() {
  const now = new Date();
  const day = String(now.getDate()).padStart(2, '0');
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const year = now.getFullYear();
  const hours = String(now.getHours()).padStart(2, '0');
  const minutes = String(now.getMinutes()).padStart(2, '0');
  const seconds = String(now.getSeconds()).padStart(2, '0');

  const fileName = `SIGEC-Pro_Backup_${day}-${month}-${year}-${hours}:${minutes}:${seconds}.json`;

  const backupData = {
    exportDate: now.toISOString(),
    system: "SIGEC-Pro",
    version: getInstalledVersion(),
    database: {
      clientes: JSON.parse(JSON.stringify(db.clientes || [])),
      contactos: JSON.parse(JSON.stringify(db.contactos || [])),
      projetos: JSON.parse(JSON.stringify(db.projetos || [])),
      interacoes: JSON.parse(JSON.stringify(db.interacoes || [])),
      interacoesProjetos: JSON.parse(JSON.stringify(db.interacoesProjetos || [])),
      deletedProjectIds: JSON.parse(JSON.stringify(deletedProjectIds || []))
    }
  };

  const jsonStr = JSON.stringify(backupData, null, 2);
  const blob = new Blob([jsonStr], { type: 'application/json' });
  const a = document.createElement('a');

  a.href = URL.createObjectURL(blob);
  a.download = fileName;
  document.body.appendChild(a);
  a.click();
  a.remove();

  if (typeof logUserActivity === 'function') {
    logUserActivity('Cópia de Segurança', `Backup do sistema "${fileName}" gerado.`);
  }

  showToast('Cópia de segurança (Backup) criada com sucesso!');
  alert(`✅ Cópia de Segurança Gerada com Sucesso!\n\nFicheiro: ${fileName}\n\nEste ficheiro contém a totalidade dos dados do seu programa (${db.clientes.length} Clientes, ${db.contactos.length} Contactos, ${db.projetos.length} Projetos).`);
}

function triggerDatabaseImport() {
  const fileInput = document.getElementById('fullDatabaseImportInput');
  if (fileInput) fileInput.click();
}

function importDatabaseJSON(event) {
  const file = event.target.files[0];
  if (!file) return;

  const confirmAction = confirm(
    "⚠️ CONFIRMAÇÃO DE REPOSIÇÃO DE DADOS:\n\n" +
    "Atenção: Está prestes a REPOR a base de dados do programa a partir do ficheiro de backup selecionado.\n\n" +
    "Esta ação irá substituir os registos atuais do sistema pelos dados da cópia de segurança.\n\n" +
    "Tem a certeza de que deseja proceder com esta reposição de dados agora?"
  );

  if (!confirmAction) {
    showToast("Reposicão de dados cancelada pelo utilizador.", "info");
    event.target.value = '';
    return;
  }

  const reader = new FileReader();
  reader.onload = async function(e) {
    try {
      const parsed = JSON.parse(e.target.result);
      const data = parsed.database || parsed.db || parsed;

      const clientesArr = data.clientes || parsed.clientes || [];
      const contactosArr = data.contactos || parsed.contactos || [];
      const projetosArr = data.projetos || parsed.projetos || [];
      const interacoesArr = data.interacoes || parsed.interacoes || [];
      const interacoesProjetosArr = data.interacoesProjetos || parsed.interacoesProjetos || [];
      const usuariosArr = data.usuarios || parsed.usuarios || null;

      if (!clientesArr && !contactosArr && !projetosArr) {
        throw new Error("O ficheiro selecionado não contém listas válidas de clientes, contactos ou projetos.");
      }

      db.clientes = Array.isArray(clientesArr) ? clientesArr : [];
      db.contactos = Array.isArray(contactosArr) ? contactosArr : [];
      db.projetos = Array.isArray(projetosArr) ? projetosArr : [];
      db.interacoes = Array.isArray(interacoesArr) ? interacoesArr : [];
      db.interacoesProjetos = Array.isArray(interacoesProjetosArr) ? interacoesProjetosArr : [];
      if (Array.isArray(usuariosArr) && usuariosArr.length > 0) {
        db.usuarios = usuariosArr;
      }
      deletedProjectIds = data.deletedProjectIds || [];

      if (parsed.version) {
        localStorage.setItem('sigec_pro_installed_version', parsed.version);
      }

      saveDatabase();

      // Sincroniza imediatamente o backup importado com o Servidor GitHub (aguarda conclusão)
      const ghToken = localStorage.getItem('sigec_pro_gh_token');
      if (ghToken && typeof syncDatabaseToGitHub === 'function') {
        await syncDatabaseToGitHub(false);
      }

      if (typeof renderHomeDashboard === 'function') renderHomeDashboard();
      if (typeof renderDatabaseOverview === 'function') renderDatabaseOverview();
      if (typeof renderClientPageMainGrid === 'function') renderClientPageMainGrid();
      if (typeof renderContactPageMainGrid === 'function') renderContactPageMainGrid();
      if (typeof renderProjectPageMainGrid === 'function') renderProjectPageMainGrid();
      if (typeof updateInstalledVersionUI === 'function') updateInstalledVersionUI();

      showToast("Base de dados reposta e sincronizada no servidor!");
      alert(`✅ Reposição e Sincronização Concluída!\n\nOs dados foram repostos a partir da cópia de segurança e salvaguardados com sucesso no servidor GitHub.\n\nRegistos carregados:\n- ${db.clientes.length} Clientes\n- ${db.contactos.length} Contactos\n- ${db.projetos.length} Projetos`);
    } catch (err) {
      console.error("Erro na reposição de dados:", err);
      showToast("Erro na reposição do ficheiro.", "danger");
      alert(`❌ Erro na Reposição de Dados:\nNão foi possível ler o ficheiro: ${err.message}`);
    }
    event.target.value = '';
  };
  reader.readAsText(file);
}

let pendingCategoryType = null;
function triggerCategoryImport(type) {
  pendingCategoryType = type;
  const input = document.getElementById('categoryImportInput');
  if (input) input.click();
}

function handleCategoryImport(event) {
  const file = event.target.files[0];
  if (!file || !pendingCategoryType) return;

  const categoryName = pendingCategoryType.toUpperCase();
  const confirmImport = confirm(
    `⚠️ CONFIRMAÇÃO DE IMPORTAÇÃO DE DADOS:\n\n` +
    `Deseja importar os registos do ficheiro "${file.name}" para a listagem de ${categoryName}?\n\n` +
    `Estes dados serão adicionados com segurança à sua base de dados atual sem apagar os registos existentes.`
  );

  if (!confirmImport) {
    showToast("Importação de dados cancelada pelo utilizador.", "info");
    event.target.value = '';
    return;
  }

  showToast(`Importação para ${categoryName} iniciada com sucesso.`);
  event.target.value = '';
}
